INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('1', '16784', NULL, '[31,48,18,40,12]', NULL, NULL, NULL, '{\"en\":\"G833\",\"ar\":\"G833\"}', 'g833', 'g833-2', '{\"en\":\"Discover a one-of-a-kind gift that blends beauty and flavor in a vibrant and luxurious arrangement. This unique design brings together the freshness of nature and the elegance of fruit in a stylish glass vase. It features 4 green apples, 6 fresh lemons, 10 yellow roses, and 3 pink lilium that add a soft feminine touch. Complementing the look are 3 chrysanthemums, kermit blooms, solidago, gypsophilia, steel grass, and natural greenery that create a perfect harmony.\\nA joyful and refreshing arrangement — ideal for bright occasions and meaningful gifts.\\nHeight approximately 60 cm.\\nWidth approximately 40 cm.\",\"ar\":\"اكتشف هدية فريدة من نوعها تجمع بين الجمال والمذاق! وينبض بالحيوية والفخامة، يجمع بين جمال الطبيعة ونضارة الفاكهة في تنسيق فريد داخل فازة أنيقة. يحتوي على 4 حبات تفاح أخضر، و6 حبات ليمون طازج، و10 ورود روز صفراء، و3 زهور ليليوم وردي تضيف لمسة أنثوية راقية، مع 3 الكريزنتيموم، و3 كيرميت، وورود السوليداجو، وجبسوفيليا وستيل قراس وخضارات طبيعية تضفي تناغمًا وأناقة على التصميم. تنسيق مثالي يعبّر عن البهجة والتجدد، مناسب للهدايا المميزة والمناسبات المشرقة.\\nالارتفاع حوالي 60 سم.\\nالعرض حوالي 40 سم.\"}', '1374', 'products/2023/06/103-50.png', '[\"products\\/gallery\\/2023\\/06\\/103-50.png\",\"products\\/gallery\\/2023\\/06\\/102-49.png\",\"products\\/gallery\\/2023\\/06\\/01.png\",\"products\\/gallery\\/2023\\/06\\/104-43.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":16784,\"wp_en_id\":15220}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '330.00', '330.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', '[\"weekly\",\"biweekly\",\"monthly\"]', '[\"3_months\",\"6_months\",\"12_months\",\"until_cancelled\"]', '3_months', 'Other', NULL, NULL, '2026-10-01 09:49:54', '2026-10-13 12:59:08', NULL);
