INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('13', '16844', NULL, '[31,19,48,18,21,24]', NULL, NULL, NULL, '{\"en\":\"G743\",\"ar\":\"G743\"}', 'g743', 'g743-2', '{\"en\":\"A bouquet thoughtfully designed by our expert florists, who carefully curated an arrangement that leaves a refined and exclusive impression, presented with elegance to our valued customers. This vibrant and harmoniously colored bouquet features light green cymbidium orchids, white lilies, and light purple baby roses, beautifully blended with pink and white roses. The design is enhanced by the rich contrast of deep purple Eustoma and alstroemeria, adding a luxurious feel to the bouquet.\\nWe added delicate finishing touches of steel grass, eucalyptus greenery, and light pink limonium, creating a captivating and graceful composition. The perfect choice for someone who deserves unforgettable moments.\\nHeight: approx. 65–70 cm\\nWidth: approx. 45–50 cm\",\"ar\":\"باقة صُممت بعناية فائقة على يد خبرائنا، الذين حرصوا على تنسيقها بذوق رفيع يترك انطباعًا جماليًا راقيًا وحصريًا، لتُقدَّم بكل تألق لعملائنا المميزين.بباقة مليئة بالأزهار بألوان متناسقة ومبهجة، حيث تحتوي على زهور السمبيديوم الأخضر الفاتح, الليليوم الأبيض, والبيبي جوري البنفسجي الفاتح , مع تداخلات الجوري الزهري الفاتح والأبيض , يكسرها الزهر الاستوما والاستومريا باللون البنفسجي الغامق لتعطي إحساس راقي للباقة، اضفنا اللمسات الساحرة الرقيقة من  الستيل غراس وخضار اليوكالبتوس مع الليمينيوم الزهري الفاتح\\nالاختيار المثالي لكل من يستحق لحظات لا تُنسى.\\nالارتفاع حوالي 65 سم إلى 70 سم.\\nالعرض حوالي 45 سم إلى 50 سم.\"}', '1324', 'products/2023/06/104-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/104-1.jpg\",\"products\\/gallery\\/2023\\/06\\/105-1.jpg\",\"products\\/gallery\\/2023\\/06\\/103-12.jpg\",\"products\\/gallery\\/2023\\/06\\/106-1.jpg\",\"products\\/gallery\\/2023\\/06\\/102-11.jpg\",\"products\\/gallery\\/2023\\/06\\/101-25.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"}],\"tags\":[],\"wp_ar_id\":16844,\"wp_en_id\":15432}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1100.00', '1100.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:49:55', '2026-10-13 12:56:10', NULL);
