\/gallery\\/2023\\/06\\/4-41.png\",\"products\\/gallery\\/2023\\/06\\/5-22.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":16852,\"wp_en_id\":14412}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '155.00', '155.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:49:55', '2026-10-13 13:14:01', NULL);
