:\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":161,\"name\":\"Thank You\",\"slug\":\"thank-you\"}],\"tags\":[],\"wp_ar_id\":16884,\"wp_en_id\":15410}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:49:57', '2026-10-13 12:56:37', NULL);
