INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('36', '16914', NULL, '[31,48,6,15,28]', NULL, NULL, NULL, '{\"en\":\"G690\",\"ar\":\"G690\"}', 'g690', 'g690-2', '{\"en\":\"A luxurious arrangement blending shades of purple and pink in perfect harmony, radiating elegance and sophistication. It features eight roses in light purple tones, three light pink Eustoma, two light purple chrysanthemums, pink lilies, three baby pink roses, and five pink orchids accented with fresh greenery. The result is a stunning bouquet that conveys refined taste and genuine emotion—an ideal gift for any special occasion.\",\"ar\":\"تنسيق فاخر يجمع تدرجات البنفسجي والوردي بتناغم ساحر يعكس الأناقة والرقي. يتكوّن من ثمانية ورود الروز بتدرجات بنفسجية، وثلاث زهور استوما وردية فاتحة، وزهرتين من الكريزنتيموم البنفسجي الفاتح، مع ليلوم وردي وثلاث بيبي روز وردية، وخمس زهور أوركيد وردية تضيف لمسة فاخرة، تتناغم جميعها مع الخضار الطبيعي لتمنح شعورًا بالدفء والجمال المتكامل. مثالي كهدية تعبّر عن الذوق الرفيع والمشاعر الصادقة في أي مناسبة.\\nالارتفاع حوالي 80 سم.\\nالعرض حوالي 60 سم.\"}', '1244', 'products/2023/06/1-32.png', '[\"products\\/gallery\\/2023\\/06\\/1-32.png\",\"products\\/gallery\\/2023\\/06\\/2-34.png\",\"products\\/gallery\\/2023\\/06\\/3-33.png\",\"products\\/gallery\\/2023\\/06\\/4-31.png\",\"products\\/gallery\\/2023\\/06\\/5-16.png\",\"products\\/gallery\\/2023\\/06\\/6-5.png\"]', NULL,