INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('51', '16968', NULL, '[31,24,13,2]', NULL, NULL, NULL, '{\"en\":\"G637\",\"ar\":\"G637\"}', 'g637', 'g637', '{\"en\":\"Expertly crafted with elegance and refined taste, this exquisite bouquet is designed to leave an unforgettable impression a refreshing and joyful gift for any occasion.\\nArranged in a stylish vase, this luxurious bouquet features 43 pieces of red roses and 20 pieces of white baby orchids. Delicate highlights of hydrangea, cymbidium white , lilies, Eustoma, Mattioli white\\nElegant greenery, plants like solidago, lucky bamboo, and steel grass, adds a classic and timeless touch to the overall design.\\nCreate beautiful moments with your loved ones through this truly premium floral masterpiece.\\nHeight: Approximately 85 to 90 cm\\nWidth: Approximately 75 to 80 cm\",\"ar\":\"صُممت هذه الباقة الأنيقة بمهارة وذوق رفيع، لتترك انطباعًا لا يُنسى. مما يجعلها هدية منعشة ومبهجة لأي مناسبة. باقة فاخرة في مزهرية تحتوي على 43 حبة من الجوري الأحمر و 20 حبة من البيبي الاوركيد الأبيض تفاصيل رقيقة تعطي إحساس عميق لوجود من بعض الازهار الأخرى مثل : الهيدرنجا والسمبيديوم الأبيض, مع الليليوم  و الاستوما والماثيولا الأبيض, والأخضارات السولي داغو و الليكي بامبو مع الستيل غراس التي تعطي ايحاء كلاسكي\\nاصنع لحظات جميلة مع أحبائك من خلال هذه التحفة الزهرية الفاخرة.\\nالارتفاع حوالي 85 سم إلى 90 سم.\\nالعرض حوالي 75 سم إلى 80 سم\"}', '1217', 'products/2023/06/105-3.png', '[\"products\\/gallery\\/2023\\/06\\/105-3.png\",\"products\\/gallery\\/2023\\/06\\/104-3.png\",\"products\\/gallery\\/2023\\/06\\/103-3.png\",\"products\\/gallery\\/2023\\/06\\/101-3.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":138,\"name\":\"Wedding\",\"slug\":\"wedding\"}],\"tags\":[],\"wp_ar_id\":16968,\"wp_en_id\":15980}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1300.00', '1300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:05', '2026-10-13 12:51:57', NULL);
