ULL, NULL, '100', '280.00', '280.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:06', '2026-10-13 12:50:54', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('63', '17006', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G596\",\"ar\":\"G596\"}', 'g596', 'g596-2', '{\"en\":\"Gift your loved ones this stunning bouquet that beautifully blends the charm of flowers with the freshness of fruits in an elegant, vibrant arrangement! The bouquet features 21 red and white roses harmoniously paired to create a captivating visual, surrounded by 5 white chrysanthemum blooms, soft touches of white limonium (3), and two delicate alstroemeria stems. A refreshing hint of greenery comes from two green hydrangeas, adding to the bouquet’s natural appeal.\\nThis beauty is completed with carefully selected fruits. : two bananas, one red apple, two mangoes, four lemons, three guavas, and a cluster of grapes that crowns the bouquet with an eye-catching touch. A luxurious arrangement that reflects refined taste—perfect as a thoughtful gift or for marking a special occasion.\\nHeight approximately 50 cm.\\nWidth approximately  50cm.\",\"ar\":\"أهدي من يعز عليك مع هذه الباقة المميزة التي تجمع بين سحر الزهور ونضارة الفواكه في تنسيق أنيق ينبض بالحياة! تتألق الباقة بـ21 وردة حمراء وبيضاء تنسجم بتناغم ساحر، يحيط بها 5 زهور كريز أبيض ولمسات ناعمة من الليمينيوم الأبيض (3) واستروميريا رقيقة (2)، مع لمسة خضراء منعشة من هيدرينجا أخضر (2). ويكتمل الجمال بفاكهة مختارة بعناية: موزتين، تفاحة حمراء، حبتين مانجو، 4 حبات ليمون، 3 جوافة، وعنقود عنب يتوّج الباقة بلمسة لافتة. تنسيق فاخر يعبّر عن الذوق الرفيع، مثالي لهدية مميزة أو لمناسبة استثنائية.\\nالارتفاع حوالي 50 سم.\\nالعرض حوالي 50 سم.\"}', '1197', 'products/2023/06/101-55.png', '[\"products\\/gallery\\/2023\\/06\\/101-55.png\",\"products\\/gallery\\/2023\\/06\\/102-52.png\",\"products\\/gallery\\/2023\\/06\\/104-46.png\",\"products\\/gallery\\/2023\\/06\\/103-52.png\"]', '{\"en\":null,\"ar\":\"<p>&lt;p&gt;&lt;span lang=\\\"AR-SA\\\" dir=\\\"RTL\\\" style=\\\"font-size:14.0pt;<br />\\nline-height:107%;font-family:Tajawal;mso-fareast-font-family:Calibri;<br />\\nmso-fareast-theme-font:minor-latin;mso-ansi-language:EN-US;mso-fareast-language:<br />\\nEN-US;mso-bidi-language:AR-SA\\\"&gt;&amp;nbsp; تشكيلة رائعة من الزهور المتناسقة لإيصال ما تريد<br />\\nمن كلمات مليئة بالمشاعر الدافئة من خلال باقة&amp;nbsp;<br />\\nأنيقة تحتوي الفواكه المنعشه مع ٥ من البيبي جوري الأحمر، والجبسوفيليا وخضار اليوكاليبتوس&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;/p&gt;</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17006,\"wp_en_id\":16056}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '400.00', '400.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:06', '2026-10-13 12:50:46', NULL);
