INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('67', '17020', NULL, '[31,19,48,18,13,52]', NULL, NULL, NULL, '{\"en\":\"G589\",\"ar\":\"G589\"}', 'g589', 'g589-2', '{\"en\":\"This luxurious bouquet of white flowers features a blend of natural beauty and elegance. The bouquet includes white Hydrangea, 6 white Baby Orchids, 5 white Alstrumeria, 10 white Roses, 6 white Carnations, 3 white eustomas, 2 white Liliums, white Limonium, and 5 white Baby Roses, complemented by fresh greenery for a refreshing and sophisticated touch. The perfect choice to add an elegant and distinctive touch to your special occasions.\",\"ar\":\"هذه باقة فاخرة من الأزهار البيضاء المميزة، التي تجمع بين تنوع الأزهار الطبيعية والجمال الخالص. تتضمن الباقة هايدرينجا أبيض، بيبي أوركيد أبيض، الستروميرا الأبيض، روز أبيض زهرة القرنفل باللون الأبيض ، والاستوما أبيض الليلوم أبيض ، لمينيوم أبيض، وبيبي روز أبيض بالإضافة إلى لمسات من الخضار الطبيعي لإضفاء لمسة من الرقي والانتعاش. إنها الخيار المثالي لإضافة لمسة أنيقة ومميزة لمناسباتك الخاصة.\\nالارتفاع حوالي 45 سم.\\nالعرض حوالي 80 سم.\"}', '1190', 'products/2023/06/101-66.png', '[\"products\\/gallery\\/2023\\/06\\/101-66.png\",\"products\\/gallery\\/2023\\/06\\/102-62.png\",\"products\\/gallery\\/2023\\/06\\/103-60.png\",\"products\\/gallery\\/2023\\/06\\/104-56.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":188,\"name\":\"PINK OCTOBER\",\"slug\":\"pink-october\"}],\"tags\":[],\"wp_ar_id\":17020,\"wp_en_id\":16084}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '575.00', '575.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:07', '2026-10-13 12:50:33', NULL);
