INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('69', '17024', NULL, '[31,48,6,18,21,12,53]', NULL, NULL, NULL, '{\"en\":\"G587\",\"ar\":\"G587\"}', 'g587', 'g587-2', '{\"en\":\"This stunning bouquet beautifully combines the elegance of pink and white flowers. It includes 10 Pink Baby Orchids, Light Pink Hydrangea, 10 Light Pink Roses, 6 White Carnations, 2 White Alstrumerias, 4 Japanese Carnations, 4 White Wax Flowers, and 2 White Liliums. This bouquet is the perfect choice to add a touch of sophistication and joy to any occasion, with its harmonious blend of vibrant, fragrant blooms that fill the air with freshness and beauty.\\nHeight approximately 65 cm.\\nWidth approximately 60 cm.\",\"ar\":\"باقة زهور رائعة تجمع بين جمال الألوان الوردية والبيضاء بأناقة استثنائية. تحتوي على 10 زهور بيبي أوركيد وردي، هايدرينجا وردي فاتح، 10 ورود وردي فاتح، 6 ورود كرنيشن أبيض، 2 زهور الستروميرا الأبيض، 4 ورود كرنيشن ياباني، 4 زهور واكس أبيض، و2 زهور ليليوم أبيض. هذه الباقة هي الاختيار المثالي لإضفاء لمسة من الرقي والبهجة على أي مناسبة، مع تناغم الألوان الزاهية والعطرة التي تملأ الأجواء بالانتعاش والجمال.\\nالارتفاع حوالي 65 سم.\\nالعرض حوالي 60 سم.\"}', '1188', 'products/2023/06/1-19.png', '[\"products\\/gallery\\/2023\\/06\\/1-19.png\",\"products\\/gallery\\/2023\\/06\\/2-21.png\",\"products\\/gallery\\/2023\\/06\\/3-20.png\",\"products\\/gallery\\/2023\\/06\\/4-20.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"},{\"id\":189,\"name\":\"White Friday\",\"slug\":\"white-friday\"}],\"tags\":[],\"wp_ar_id\":17024,\"wp_en_id\":16092}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '530.00', '530.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:07', '2026-10-13 12:50:26', NULL);
