:\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":188,\"name\":\"PINK OCTOBER\",\"slug\":\"pink-october\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17034,\"wp_en_id\":16112}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '280.00', '280.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:07', '2026-10-13 12:50:20', NULL);
