INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('78', '17082', NULL, '[31,48,18,21,45,25,12]', NULL, NULL, NULL, '{\"en\":\"G493\",\"ar\":\"G493\"}', 'g493', 'g493-2', '{\"en\":\"A stunning bouquet combining beauty and purity, featuring 5 pieces of elegant white liliums and 3 pieces of fresh green lipeedium flowers. This bouquet is elegantly arranged with modern wrapping in a refreshing green shade, adding a touch of sophistication and tranquility. Perfect for any occasion, this bouquet radiates luxury and calmness. Finished with a delicate white ribbon, it’s the ideal choice for expressing appreciation and celebration.\\nHeight approximately 65 cm.\\nWidth approximately 40 cm.\",\"ar\":\"باقة ورود مميزة تجمع بين الجمال والنقاء، تتكون من 5 قطع من زهور الليليوم الأبيض الرائعة و3 قطع من زهور اللبيديوم الخضراء. تمتاز الباقة بتنسيق عصري وأنيق، مع تغليف مميز باللون الأخضر يضيف لمسة من الرقي والانتعاش. تعتبر هذه الباقة المثالية لأي مناسبة، حيث تضفي جوًا من الفخامة والهدوء. مع لمسة نهائية من الشريط الأبيض، ستكون هذه الباقة الخيار الأمثل للتعبير عن التقدير والاحتفاء.\\nالارتفاع حوالي 65 سم.\\nالعرض حوالي 40 سم.\"}', '1156', 'products/2023/06/1-8.png', '[\"products\\/gallery\\/2023\\/06\\/1-8.png\",\"products\\/gallery\\/2023\\/06\\/2-38.png\",\"products\\/gallery\\/2023\\/06\\/3-9.png\",\"products\\/gallery\\/2023\\/06\\/4-10.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":161,\"name\":\"Thank You\",\"slug\":\"thank-you\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17082,\"wp_en_id\":16204}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '180.00', '180.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:08', '2026-10-13 12:49:47', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('79', '17084', NULL, '[31,50,48,18,23,10]', NULL, NULL, NULL, '{\"en\":\"G492\",\"ar\":\"G492\"}', 'g492', 'g492-2', '{\"en\":\"Add a touch of elegance and sophistication to your day with the Purple Baby Orchid Bouquet. This stunning arrangement combines vibrant shades of purple and fresh green tones, bringing a sense of freshness and natural beauty. Wrapped in elegant paper and tied with a soft pink ribbon, it’s the perfect gift to express refined taste and heartfelt emotions on any occasion.\\nHeight approximately 60 cm.\\nWidth approximately 40 cm.\",\"ar\":\"أضف لمسة من الأناقة والرقي إلى يومك مع باقة بيبي أوركيد بنفسجي الفاخرة. تجمع هذه الباقة الساحرة بين درجات البنفسجي المبهجة والأخضر الحيوي لتمنحك إحساساً بالانتعاش والجمال الطبيعي. مغلّفة بورق أنيق ومربوطة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الذوق الرفيع والمشاعر الراقية في كل مناسبة.\\nالارتفاع حوالي 60 سم.\\nالعرض حوالي 40 سم.\"}', '1155', 'products/2023/06/101-61.png', '[\"products\\/gallery\\/2023\\/06\\/101-61.png\",\"products\\/gallery\\/2023\\/06\\/102-57.png\",\"products\\/gallery\\/2023\\/06\\/103-56.png\",\"products\\/gallery\\/2023\\/06\\/104-51.png\",\"products\\/gallery\\/2023\\/06\\/105-34.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":146,\"name\":\"Purple\",\"slug\":\"purple\"}],\"tags\":[],\"wp_ar_id\":17084,\"wp_en_id\":16208}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '150.00', '150.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:08', '2026-10-13 12:49:42', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('80', '17088', NULL, '[31,19,48,18,3,13,25]', NULL, NULL, NULL, '{\"en\":\"G490\",\"ar\":\"G490\"}', 'g490', 'g490-2', '{\"en\":\"Celebrate your special moments with this stunning bouquet of double roses in beautiful pink gradients, featuring 20 rose double color. green Lepidium, it adds a natural touch and elegant texture. This bouquet is masterfully arranged to add a unique charm to any occasion, whether it’s a birthday, anniversary, or a heartfelt gift. With its exquisite pink ribbon, this bouquet is the perfect choice to express love and beauty.\",\"ar\":\"تألقي بأجمل لحظاتك مع هذا الباقة الرائعة من ورد الروز المزدوج بتدرجات اللون الوردي، المكونة من 20 وردة روز فاخرة، تنبض بالجمال والرقة. تزينها 5 قطع من اللبيديوم الأخضر لإضافة لمسة طبيعية وملمس أنيق. تتميز هذه الباقة بتنسيق مذهل يضفي على كل مناسبة سحرًا خاصًا، سواء كان عيد ميلاد، أو ذكرى مميزة، أو حتى هدية تعبر عن مشاعرك. مع ربطتها الوردية الفاخرة، تعد هذه الباقة الخيار المثالي للتعبير عن الحب والجمال.\\nالارتفاع حوالي 40 سم.\\nالعرض حوالي 35 سم.\"}', '1153', 'products/2023/06/1-3.png', '[\"products\\/gallery\\/2023\\/06\\/1-3.png\",\"products\\/gallery\\/2023\\/06\\/2-5.png\",\"products\\/gallery\\/2023\\/06\\/3-4.png\",\"products\\/gallery\\/2023\\/06\\/4-5.png\",\"products\\/gallery\\/2023\\/06\\/5-5.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":161,\"name\":\"Thank You\",\"slug\":\"thank-you\"}],\"tags\":[],\"wp_ar_id\":17088,\"wp_en_id\":16216}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '190.00', '190.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:08', '2026-10-13 12:49:36', NULL);
