INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('101', '17162', NULL, '[31,19,51,48,18,21,23]', NULL, NULL, NULL, '{\"en\":\"G402\",\"ar\":\"G402\"}', 'g402', 'g402-2', '{\"en\":\"A lively and cheerful floral arrangement that combines bright colors with a modern touch, beautifully basket. The arrangement includes 25 yellow roses symbolizing joy and positivity, 6 delicate alstroemeria blooms, and 3 lush Lepidium stems for a fresh green balance. It also features 5 pure white Eustoma flowers adding a touch of elegance, 5 vibrant solidago stems for extra brightness, and 6 white chrysanthemums that bring fullness and sophistication. The design is completed with 5 white and yellow balloons, adding a playful and celebratory vibe. Perfect for happy occasions and gifts that spread joy and positivity everywhere.\",\"ar\":\"تنسيق زهري مفعم بالحيوية والسعادة، يجمع بين الألوان المشرقة واللمسة العصرية في سلة أنيقة من الخوص الطبيعي. يضم التنسيق 25 وردة صفراء متألقة ترمز للتفاؤل والبهجة، مع 6 زهور ألستروميريا الرقيقة، و3 عيدان لبيديوم تضيف لمسة من التوازن الأخضر الطبيعي. كما يحتوي على 5 أزهار ستوما بيضاء تمنح الباقة لمسة من النقاء، و5 زهور سوليداجو الصفراء الزاهية التي تعزز الإشراقة، إلى جانب 6 كريزنتيموم أبيض يضفي امتلاءً وأناقة. يكتمل التصميم بلمسة مرحة من 5 بالونات بيضاء وصفراء تضيف روحًا احتفالية مبهجة. هذه الباقة مثالية للمناسبات السعيدة والهدايا التي تنشر الفرح والإيجابية في كل مكان.\\nالارتفاع حوالي 60 سم.\\nالعرض حوالي 55 سم.\"}', '1114', 'products/2023/06/1-42.png', '[\"products\\/gallery\\/2023\\/06\\/1-42.png\",\"products\\/gallery\\/2023\\/06\\/2-48.png\",\"products\\/gallery\\/2023\\/06\\/3-46.png\",\"products\\/gallery\\/2023\\/06\\/4-44.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"}],\"tags\":[],\"wp_ar_id\":17162,\"wp_en_id\":16366}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:15', '2026-10-13 12:47:26', NULL);
