INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('112', '17186', NULL, '[31,19,48,18,21,13,52]', NULL, NULL, NULL, '{\"en\":\"G132\",\"ar\":\"G132\"}', 'g132', 'g132-2', '{\"en\":\"A luxurious floral arrangement that blends shades of pink in perfect harmony and refined elegance. It features 8 roses in soft pink tones, 3 pink and white liliums, 5 fragrant pink mathiyola, and 3 light pink baby roses. Enhanced with light pink Eustoma, deep purple wax flowers, 5 light chrysanthemums, and fresh greenery that adds a natural balance. A perfect choice to express appreciation, celebrate joy, or mark any special moment with beauty and grace.\",\"ar\":\"تنسيق زهري فاخر يجمع بين درجات اللون الوردي بتناسقٍ مفعم بالجمال والذوق الرفيع. يضم 8 روز وردية بتدرجات مختلفة، و3 زهور ليليوم وردية وبيضاء تضفي لمسة فاخرة، مع 5 زهور ماثيولا وردية عطرة، و3 بيبي روز وردية فاتحة تضفي نعومة خاصة. يتكامل التنسيق بزهور استوما وردية فاتحة وواكس بنفسجي داكن و5 كريزنتيموم بنفسجية فاتحة، مع خضار لتتناغم جميعها بحيوية متكاملة. اختيار مثالي للتعبير عن التقدير، الفرح، أو للاحتفاء بكل لحظة مميزة.\\nالارتفاع حوالي 40 سم.\\nالعرض حوالي 30 سم.\"}', '1101', 'products/2023/06/1-23.png', '[\"products\\/gallery\\/2023\\/06\\/1-23.png\",\"products\\/gallery\\/2023\\/06\\/2-25.png\",\"products\\/gallery\\/2023\\/06\\/3-24.png\",\"products\\/gallery\\/2023\\/06\\/4-22.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":188,\"name\":\"PINK OCTOBER\",\"slug\":\"pink-october\"}],\"tags\":[],\"wp_ar_id\":17186,\"wp_en_id\":16422}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:16', '2026-10-13 12:46:06', NULL);
