INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('120', '17202', NULL, '[31,48,18,13]', NULL, NULL, NULL, '{\"en\":\"G046\",\"ar\":\"G046\"}', 'g046', 'g046-2', '{\"en\":\"Add a touch of elegance and sophistication to any occasion with the enchanting Pink Lilium and Rose Bouquet. This exquisite arrangement features 7 luxurious pink liliums and 12 light pink roses that embody grace and romance, complemented by 3 stems of pink limonium for a delicate, natural finish. Beautifully arranged in a sleek glass vase and adorned with a soft pink ribbon, this bouquet makes the perfect gift to express love, gratitude, or celebration in a refined and unforgettable way.\\nHeight approximately 65 cm.\\nWidth approximately 45 cm.\",\"ar\":\"أضف لمسة من الأناقة والرقي إلى أي مناسبة مع باقة “الليليوم والروز الوردي” الساحرة. تجمع هذه التشكيلة بين 7 زهور ليليوم وردية فخمة و12 روز وردية فاتحة تعبّر عن النعومة والرومانسية، تتناغم معها 3 فروع من الليمنيوم الوردي التي تضيف لمسة من الخفة والجمال الطبيعي. تأتي الباقة مرتّبة بعناية في فازة زجاجية أنيقة ومزيّنة بشريط وردي ناعم، لتكون هدية مثالية تعبّر عن الحب، الامتنان، أو التهنئة بأسلوب راقٍ ولا يُنسى.\\nالارتفاع حوالي 65 سم.\\nالعرض حوالي 45 سم.\"}', '1092', 'products/2023/06/01-2.png', '[\"products\\/gallery\\/2023\\/06\\/01-2.png\",\"products\\/gallery\\/2023\\/06\\/2-44.png\",\"products\\/gallery\\/2023\\/06\\/3-42.png\",\"products\\/gallery\\/2023\\/06\\/4-39.png\",\"products\\/gallery\\/2023\\/06\\/5-21.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17202,\"wp_en_id\":16462}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '380.00', '380.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:17', '2026-10-13 12:45:25', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('121', '17206', NULL, '[31,20,24]', NULL, NULL, NULL, '{\"en\":\"G172\",\"ar\":\"G172\"}', 'g172', 'g172-2', '{\"en\":\"This luxurious arrangement of white roses and white baby orchids is elegantly displayed in a simple glass vase, adding a touch of sophistication and tranquility to any space. The arrangement includes 12 soft white roses and 10 white baby orchids, with a meticulous design that highlights the beauty of nature in every detail. This arrangement is the perfect choice for decorating spaces or as a special gift for any occasion, offering a blend of elegance and softness.\\nHeight approximately 20 cm.\\nWidth approximately 20 cm.\",\"ar\":\"تتميز هذه التشكيلة الفاخرة التي تضم 80 حبه من الجوري الاحمر بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. مع تنسيق متقن 10حبه من الكريزنتيموم الابيض يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.\\nالارتفاع حوالي 75 سم.\\nالعرض حوالي 35 سم.\"}', '1090', 'products/2023/06/101-76.png', '[\"products\\/gallery\\/2023\\/06\\/101-76.png\",\"products\\/gallery\\/2023\\/06\\/102-71.png\",\"products\\/gallery\\/2023\\/06\\/103-69.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"}],\"tags\":[],\"wp_ar_id\":17206,\"wp_en_id\":16640}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '800.00', '800.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:17', '2026-10-13 12:41:37', NULL);
