INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('149', '17324', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G615\",\"ar\":\"G615\"}', 'g615', 'g615-2', '{\"en\":\"Fill their lives with unforgettable moments by gifting this vibrant vase that bursts with energy and natural beauty! A luxurious blends the elegance of flowers with the freshness of fruits. At its heart lies a fresh pineapple, surrounded by clusters of red grapes, complemented by red and green apples that add a touch of color harmony. Twelve oranges and delicious strawberries bring the whole bouquet to life\\nThe arrangement blossoms with five elegant red tulips and two white gerbera flowers radiating purity, accented by two delicate white wax blooms and two lipeediums, all beautifully framed with natural greenery that enhances the overall appeal. Perfect for gifting on sophisticated occasions or to adorn your space with a touch of creativity and natural elegance.\\nHeight approximately 50 cm.\\nWidth approximately 45 cm.\",\"ar\":\"املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الفازة النابضة بالحياة التي تنبض بالحيوية والجمال الطبيعي! تنسيق فاخر يجمع بين فخامة الزهور ونضارة الفواكه، يتوسطه أناناس طازج محاط بعناقيد من العنب الأحمر، وتفاح أحمر وأخضر يضفيان لمسة من التوازن اللوني، مع 12 حبة برتقال وفراولة شهية تملأ الباقة بالحيوية. وتزهر الباقة بـ5 زهور توليب حمراء أنيقة، وحبتان من الجربيرا البيضاء التي تنبض بالنقاء، مع لمسات ناعمة من الواكس الأبيض وحبتان من اللبيديوم، محاطة بخضار طبيعي يعزز من جاذبية التنسيق. مثالية للإهداء في المناسبات الراقية أو لتزيين أجواءك بلمسة من الإبداع والجمال الطبيعي.\\nالارتفاع حوالي 50 سم.\\nالعرض حوالي 45 سم.\"}', '944', 'products/2023/06/102-53.png', '[\"products\\/gallery\\/2023\\/06\\/102-53.png\",\"products\\/gallery\\/2023\\/06\\/101-56.png\",\"products\\/gallery\\/2023\\/06\\/104-47.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17324,\"wp_en_id\":16576}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '460.00', '460.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:20', '2026-10-13 12:43:22', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('150', '17326', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G613\",\"ar\":\"G613\"}', 'g613', 'g613-2', '{\"en\":\"A chic arrangement that beautifully blends the freshness of fruits with the elegance of flowers in a modern, luxurious design, all presented in a clear vase adorned with soft pink blooms. It features perfectly arranged fresh strawberries on top, along with green and red apples, pomegranate, and pear. Floral touches include 2 chrysanthemums, 3 kermit flowers, and delicate white gypsophilia, complemented by natural greenery for a complete. perfect for upscale gifts and special occasions.\\nHeight approximately 45 cm.\\nWidth approximately 25 cm.\",\"ar\":\"تنسيق أنيق يجمع بين نضارة الفاكهة وجمال الزهور في تصميم عصري فاخر داخل فازة شفافة مزينة بورود وردية. يحتوي على فراولة طازجة بتوزيع متناسق في الأعلى، وتفاح أخضر وأحمر، ورمان، وكمثرى، مع لمسات زهرية من الكريزنتيموم البنفسجي والكيرميت الأخضر وجبسوفيليا البيضاء تضيف نعومة وأناقة، إلى جانب خضار تنسيقي يمنح مظهرًا طبيعيًا متكاملًا. تصميم مثالي يجمع بين الحيوية والفخامة، مناسب للهدايا الراقية والمناسبات المميزة.\\nالارتفاع حوالي 45 سم.\\nالعرض حوالي 25 سم\"}', '943', 'products/2023/06/103png-front.png', '[\"products\\/gallery\\/2023\\/06\\/103png-front.png\",\"products\\/gallery\\/2023\\/06\\/104-44.png\",\"products\\/gallery\\/2023\\/06\\/102-50.png\",\"products\\/gallery\\/2023\\/06\\/101-53.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17326,\"wp_en_id\":16580}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '220.00', '220.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:20', '2026-10-13 12:43:16', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('151', '17328', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G614\",\"ar\":\"G614\"}', 'g614', 'g614-2', '{\"en\":\"Create unforgettable moments with this vibrant bouquet, complete with a luxurious fruit and flower basket. Designed with artistic flair that combines presence and freshness, it contains pineapples, three large oranges, two red cherries, three bananas, fresh strawberries, and clusters of green grapes. It is decorated with 20 red roses, white geraniums, three chrysanthemums, four white baby orchids, four white wax flowers, and three lepidium flowers. This bouquet creates a balance of beauty and vitality, making it a wonderful and distinctive gift for various festivals.\\nHeight Approximately 40 cm\\nWidth Approximately 35 cm\",\"ar\":\"املأ حياتهم بلحظات لا تُنسى من خلال إهداء هذه الباقة النابضة بالحياة بسلة فواكه وزهور بطابع ريفي فاخر، مصممة بذوق فني يجمع بين الطبيعة والنضارة، تحتوي على أناناس، ثلاث حبات برتقال كبير، حبتين من التفاح الأحمر، ثلاث حبات موز، فراولة طازجة، وعناقيد عنب أخضر، وتتزين بـ 20 وردة روز حمراء أنيقة، زهرات الجربيرا البيضاء، ثلاث حبات من الكريزنتيموم الأبيض، أربع زهرات بيضاء بيبي أوركيد، أربع زهرات واكس أبيض، وثلاثة زهرات لبيديوم ، لتمنح السلة مظهرًا متوازنًا يجمع بين الجمال والحيوية، وتناسب مختلف المناسبات كهدية راقية ومميزة.\\nالارتفاع حوالي40سم\\nالعرض حوالي 35سم\"}', '901', 'products/2023/06/103-front-1.png', '[\"products\\/gallery\\/2023\\/06\\/103-front-1.png\",\"products\\/gallery\\/2023\\/06\\/101-51.png\",\"products\\/gallery\\/2023\\/06\\/1012.png\",\"products\\/gallery\\/2023\\/06\\/102-47.png\"]', '{\"en\":null,\"ar\":\"<p>عبّر عن حبك بهدية من الفواكه الطبيعية واصنع ألطف الذكريات في ذهن من أحببت مع مع أجمل الأزهار المُنعشة للروح.<br />\\nتحتوي على الأنواع التالية من الزهور: الروز الأبيض، الجيبسوفيليا البيضاء، خضارات الإستيل، مجموعة من الخضارات الطبيعية.<br />\\nتحتوي على الأنواع التالية من الفواكه: الليمون، البرتقال.<br />\\nالارتفاع حوالي 40 سم إلى 50 سم.<br />\\nالعرض حوالي 35 سم إلى 25 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17328,\"wp_en_id\":14484}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '460.00', '460.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:13:47', NULL);
