INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('153', '17336', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G610\",\"ar\":\"G610\"}', 'g610', 'g610-2', '{\"en\":\"A luxurious basket with an elegant arrangement that combines natural flowers and fresh fruits. It includes a box of red Rocket apples, 500g and 200g of blueberries, along with 10 white roses, 4 kermit blooms, 1 green hydrangea, 4 white eustnoma, 5 white carnations, 4 white alstroemeria stems, white lilium, and 3 chrysanthemums. Accented with coordinating greenery for a refreshing, elegant touch — all beautifully presented in a stylish basket perfect for any occasion.\\nHeight approximately 65 cm.\\nWidth approximately 45 cm.\",\"ar\":\"سلة فاخرة بتنسيق أنيق تجمع بين الزهور الطبيعية والفاكهة الطازجة، تحتوي على تفاح روكيت أحمر (صندوق)، توت أزرق 500 غرام، توت أزرق 200 غرام، ورد أبيض 10 حبات، كيرميت 4 حبات، هايدرينجا أخضر حبة واحدة، استوما أبيض 4 حبات، كرنيشن أبيض 5 حبات، أستروميريا 3 حبات، ليليوم أبيض، والكريزنتيموم 3 حبات، مع خضار تنسيقي يضيف لمسة من الانتعاش والجمال، مقدمة في سلة أنيقة تناسب جميع المناسبات.\\nالارتفاع حوالي 65 سم.\\nالعرض حوالي 45 سم.\"}', '895', 'products/2023/06/104-41.png', '[\"products\\/gallery\\/2023\\/06\\/104-41.png\",\"products\\/gallery\\/2023\\/06\\/105-29.png\",\"products\\/gallery\\/2023\\/06\\/102-48.png\"]', '{\"en\":null,\"ar\":\"<p>امنحهم الحب وأدخل الفرح في حياة من تحب من خلال باقة مكونة من فواكه وأزهار تُنعش الحواس. تحتوي على الأنواع التالية من الزهور: الروز الأصفر، الليليوم الوردي الغامق، السمبيديوم الأخضر، الواكس فلاور الأبيض، خضارات اليوكاليبتوس، خضارات الإستيل، الجيبسوفيليا البيضاء. تحتوي على الفواكه التالية: التفاح الأخضر، الليمون، العنب. الارتفاع حوالي 30 سم إلى 40 سم. العرض حوالي 25 سم إلى 35 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17336,\"wp_en_id\":14488}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:13:41', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('154', '17338', NULL, '[31,17,19,50,51,48,6,18,21,26,3,10]', NULL, NULL, NULL, '{\"en\":\"G455\",\"ar\":\"G455\"}', 'g455', 'g455-2', '{\"en\":\"Our skilful florists have created this elegant bouquet to help you to be the reason behind their happiness. You will positively lighten up their day by gifting a sumptuous bouquet that consists of striking Blue Hydrangea, and White Gypsophila combined with Pink Lilium and Dark Purple Eustoma mixed in with numerous beautiful Pink and Purple Roses. To complement this spectacular bouquet, we have included some gorgeous Dark Purple Statice along with Green Kermit, Eucalyptus Leaves and Pink Chrysanthemum to add a touch of sweetness and greenery. This striking vase bouquet is a present sure to make a lasting impression and bring a lovely smile! The height is approximately 35 cm to 45 cm. The width is approximately 30 cm to 40 cm.\",\"ar\":\"كن ذات بصمة موثرة في حياة أحبتك وعبّر عن اشتياقك بأزهار مُنعشة. باقة فخمة تتكون من الهيدرينجيا الزرقاء المذهلة والجيبسوفيليا باللون الأبيض مع الليليوم الوردي والإيستوما باللون البنفسجي الداكن. امنحهم الإحساس بأجمل اللحظات من خلال الروز باللون الوردي والبنفسجي مع زهور الإيستاتيس البنفسجية والكيراميت الأخضر الرائع، بالإضافة إلى خضارات الإكلابتوس وأزهار الكريزنتيموم الوردية لوضع لمسة من الأناقة والخضرة في باقة رائعة ستترك انطباعًا جميلًا لدي من تحب.\\nالارتفاع حوالي 35 سم إلى 45 سم.\\nالعرض حوالي 30 سم إلى 40 سم.\"}', '740', 'products/2023/06/g45520jeddah20flower20to20jeddah-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g45520jeddah20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g45520jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g455-send-flowers-to-jeddah-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":146,\"name\":\"Purple\",\"slug\":\"purple\"}],\"tags\":[],\"wp_ar_id\":17338,\"wp_en_id\":14532}', NULL, NULL, NULL, NULL, NULL, NULL, '0', '650.00', '650.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:13:20', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('155', '17342', NULL, '[31,24]', NULL, NULL, NULL, '{\"en\":\"G449\",\"ar\":\"G449\"}', 'g449', 'g449-2', '{\"en\":\"A bright, colourful bouquet that has cheer written all over it, as it consists of Light Green and Pink coloured Hydrangea along with Pink And White Lilium which are combined with White Dico, Pink Veronica and Pink Eustoma mixed in with White Waxflower, White Hydrangea, and Green Kermit as well as White Calla and White Roses to create the ultimate picture of luxury and love in this marvellous present!. We have also included just the right number of the beautiful White and Pink Statice flowers along with White and Purple Chrysanthemum, which plays a fundamental role in complementing this striking bouquet. The height is approximately 40 cm to 50 cm. The width is approximately 40 cm to 50 cm.\",\"ar\":\"عبّر عن حبك بعبق الزهور المُنعشة للروح واصنع أجمل اللحظات في حياة أحبتك من خلال باقة مكونة من الهيدرينجيا باللون الأخضر الفاتح والوردي مع الليليوم باللون أبيض والوردي، بالإضافة إلى زهور الفيرونيكا والإستوما الوردية الجميلة مع زهور الديكو والواكس فلاور باللون الأبيض. انعش حواس أحبتك بأجمل الزهور كالهيدرينجيا والكالا باللون الأبيض مع الكيرميت الأخضر وزهور الإيستاتيس والروز باللون الأبيض والوردي الرائع، بالإضافة إلى الكريزنتيموم باللون الأبيض والبنفسجي الآسر للقلب.\\nالارتفاع حوالي 40 سم إلى 50 سم.\\nالعرض حوالي 40 سم إلى 50 سم.\"}', '729', 'products/2023/06/g44920jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g44920jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g44920send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g44920send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g449-jeddah-flowers-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"}],\"tags\":[],\"wp_ar_id\":17342,\"wp_en_id\":14936}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1000.00', '1000.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:05:41', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('156', '17344', NULL, '[31,24,45,12]', NULL, NULL, NULL, '{\"en\":\"G448\",\"ar\":\"G448\"}', 'g448', 'g448-2', '{\"en\":\"You will confidently lighten up their day by gifting a luxurious bouquet that consists of striking White Cymbidium, and White Phena Lipsus mixed in with several Green and White Hydrangea along with White Tulips, White Baby Orchids and White Baby Roses to add a touch of sweetness. Also, it contains the White Eustoma and White Lilium which are combined with White Waxflower and Twisted Bamboo mixed in with Steel Grass. Our skilled florists have designed this exquisite bouquet that will make you the reason for their dazzling smile. The height is approximately 75 cm to 85 cm. The width is approximately 35 cm to 45 cm.\",\"ar\":\"هدية مُغلفة بحب لتُرسل أجمل المشاعر وأصدقها. مجموعة من أجمل الأزهار المختارة بعناية مثل السمبيديوم والفيلينوبسيس الأبيض مع زهور الهيدرينجيا باللونين الأخضر والأبيض. ارسم البسمة على وجوه أحبتك وكن السبب وراء سعادتهم من خلال باقة تحتوي على التوليب والبيبي أوركيد باللون الأبيض مع البيبي روز والإستوما البيضاء، بالإضافة إلى الليليوم والواكس فلاور الأبيض مع خضارات البامبو الملتوية وخضارات الإستيل الرائعة.عبّر عن حبك بهدية من الزهور الطبيعية واصنع أجمل الذكريات في ذهن من أحببت.\\nالارتفاع حوالي 75 سم إلى 85 سم.\\nالعرض حوالي 35 سم إلى 45 سم.\"}', '728', 'products/2023/06/g44820jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g44820jeddah20flowers20delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17344,\"wp_en_id\":16358}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1300.00', '1300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 12:47:27', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('157', '17350', NULL, '[31,5,19,51,48,18,21,23,10]', NULL, NULL, NULL, '{\"en\":\"G445\",\"ar\":\"G445\"}', 'g445', 'g445-2', '{\"en\":\"Mindfully crafted and designed by our professional florists, this selection of delicate Dark Purple Veronica and Purple Chrysanthemum combined with Purple Baby Roses and Purple Statice flowers which are synonymous with beauty and luxury. Adding to the charm of this bouquet is the Dark Purple Eustoma and the Purple Roses mixed in with the right amount of Steel Grass and Asparagus Leaves. With numerous textures and shades, this striking vase bouquet of a stylish and chic collection of blooms is a floral masterpiece suited for every occasion in any season!\\nThe height is approximately 25 cm to 35 cm.\\nThe width is approximately 15 cm to 25 cm.\",\"ar\":\"قد لا تجد عبارات مناسبة للتعبير عن مشاعرك الصادقة ولكن يمكنك إظهار نقاء قلبك من خلال هذه المجموعة المختارة بعناية من الأزهار الجذابة كالفيرونيكا باللون البنفسجي الداكن والكريزنتيموم البنفسجي مع البيبي روز والإيستاتيس باللون البنفسجي. امنح أحبتك الإحساس بالحب وانعش حواسهم بزهور الإيستوما والروز البنفسجية مع خضارات الإستيل وخضارات الإسباراجوس الخلابة. الارتفاع حوالي 25 سم إلى 35 سم.\\nالعرض حوالي 15 سم إلى 25 سم.\"}', '725', 'products/2023/06/g44520send20flower20to20jeddah-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g44520send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g44520send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g445-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":141,\"name\":\"Best Seller\",\"slug\":\"best-seller\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":146,\"name\":\"Purple\",\"slug\":\"purple\"},{\"id\":194,\"name\":\"\\u0627\\u0644\\u0623\\u0641\\u0636\\u0644 \\u0645\\u0628\\u064a\\u0639\\u0627\\u064b\",\"slug\":\"%d8%a7%d9%84%d8%a3%d9%81%d8%b6%d9%84-%d9%85%d8%a8%d9%8a%d8%b9%d8%a7%d9%8b\"}],\"tags\":[],\"wp_ar_id\":17350,\"wp_en_id\":14536}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:13:17', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('158', '17352', NULL, '[31,19,50,48,18,4,3,13,52]', NULL, NULL, NULL, '{\"en\":\"G444\",\"ar\":\"G444\"}', 'g444', 'g444-2', '{\"en\":\"Our expert florists will pick the most desirable combination of blooms to design a sumptuous vase bouquet of Pink Hydrangea and Pink Veronica arranged with White and Pink Roses which are mixed in with Pink Lilium and White Eustoma for added beauty and delight. To complement this marvellous bouquet, we have also included some lovely Purple Waxflowers and Snake Bamboo along with Steel Grass, which are perfectly highlighted by just the appropriate amount of White Chrysanthemum. Be the one who encourages and lightens up their day! The colourful blooms are an absolute choice for any special occasion! The height is approximately 35 cm to 45 cm. The width is approximately 25 cm to 35 cm.\",\"ar\":\"ضع بصمتك الموثرة في حياة من تحب وعبّر عن أحاسيسك الراقية من خلال باقة فاخرة تحتوي على الهيدرينجيا وفيرونيكا باللون الوردي مع الروز باللون الأبيض والوردي، بالاضافة إلى الليليوم الوردي والإيستوما البيضاء. إصنع أجمل الذكريات في أذهان أحبتك مع جمال زهور الكريز\\nالارتفاع حوالي 35 سم إلى 45 سم. العرض حوالي 25 سم إلى 35 سم\"}', '724', 'products/2023/06/g44420send20flower20to20jeddah-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g44420send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g44420send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g444-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":188,\"name\":\"PINK OCTOBER\",\"slug\":\"pink-october\"}],\"tags\":[],\"wp_ar_id\":17352,\"wp_en_id\":14540}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '550.00', '550.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:25', '2026-10-13 13:13:14', NULL);
