INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('167', '17372', NULL, '[31,19,48,18,21,22,3,23,13,12]', NULL, NULL, NULL, '{\"en\":\"G429\",\"ar\":\"G429\"}', 'g429', 'g429-2', '{\"en\":\"A vibrant vase bouquet that is like a passionate embrace which delivers your sentiments to someone extraordinary. A stylish gathering of White Hydrangea and Light Pink Roses mixed in with Pink Hypericum and White Lilium along Pink Waxflowers and beautiful White Baby Orchid. To complement this marvellous bouquet, we have also included some pretty Eryngium and Steel Grass as well as Snake Bamboo. It’s more than a gift – it’s a way to reveal your emotions to them. The height is approximately 30 cm to 40 cm. The width is approximately 30 cm to 40 cm.\",\"ar\":\"اهتم بأحبائك واصنع لحظات جميلة لا تنسى من خلال باقة في مزهرية نابضة بالحياة مكونة من الهيدرينجيا البيضاء والروز الوردي مع الهايبركم الوردي والليليوم الأبيض، بالإضافة إلى الواكس فلاور الوردي والبيبي أوركيد الأبيض الجميل مع الإيرانجيوم وخضارات الإستيل وخضارات البامبو الملتوية. إنها أكثر من مجرد هدية – إنها وسيلة للكشف عن مشاعرك الصادقة لهم.\\nالارتفاع حوالي 30 سم إلى 40 سم.\\nالعرض حوالي 30 سم إلى 40 سم.\"}', '709', 'products/2023/06/g42920jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g42920jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g42920send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g429-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17372,\"wp_en_id\":14560}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:26', '2026-10-13 13:12:52', NULL);
