",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17386,\"wp_en_id\":14576}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:27', '2026-10-13 13:12:41', NULL);
