INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('184', '17416', NULL, '[31,5,19,48,18,45,3,23,12]', NULL, NULL, NULL, '{\"en\":\"G393\",\"ar\":\"G393\"}', 'g393', 'g393-2', '{\"en\":\"This elegant arrangement blends purity and sophistication in one luxurious design, featuring 5 white roses, graceful white lilies, 3 white chrysanthemums, 3 white limonium stems, and fresh greenery for a perfectly balanced and lively look. Presented in a sleek glass vase, it showcases a harmony of simplicity and refined beauty. Ideal as a thoughtful gift or a stylish touch to brighten any space.\\nHeight approximately 25 cm.\\nWidth approximately 20 cm.\",\"ar\":\"تجمع هذه التشكيلة الفريدة بين النقاء والأناقة في تنسيق واحد فاخر، حيث تضم باقة من الروز الأبيض (5 وردات) والليلوم الأبيض الرقيق، مع لمسات من الكريزنتيموم الأبيض (3) واللمينيوم الأبيض (3) وأوراق الخضار الطبيعية التي تضيف توازناً جميلاً ولمسة من الحيوية. يأتي التنسيق داخل مزهرية زجاجية أنيقة تعكس بساطة التصميم وجمال التفاصيل. إنها الهدية المثالية لكل المناسبات أو لإضافة لمسة من الصفاء والجمال لأي مكان.\\nالارتفاع حوالي 25 سم.\\nالعرض حوالي 20 سم.\"}', '673', 'products/2023/06/105-38.png', '[\"products\\/gallery\\/2023\\/06\\/105-38.png\",\"products\\/gallery\\/2023\\/06\\/104-64.png\",\"products\\/gallery\\/2023\\/06\\/103-70.png\",\"products\\/gallery\\/2023\\/06\\/101-77.png\",\"products\\/gallery\\/2023\\/06\\/102-72.png\"]'