INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('186', '17420', NULL, '[31,19,6,18,13]', NULL, NULL, NULL, '{\"en\":\"G391\",\"ar\":\"G391\"}', 'g391', 'g391-2', '{\"en\":\"This selection is a vase bouquet of Baby Fushi roses, light purple roses, and chrysanthemums, with light pink roses. With the beautiful addition of dark purple Eustoma to give a harmonious impression, with a touch of light purple Limonium. undoubtedly impress your admired one! Spoil them with our gorgeous vase bouquet to show them just how much they mean to you.\\nHeight approximately 30 cm.\\nWidth approximately 40 cm.\",\"ar\":\"هذه المجموعة عبارة عن باقة مزهرية من ورود بيبي فوشي، والجوري البنفسجية الفاتحة، والكريزنتيموم، مع الجوري الوردي الفاتح. مع إضافة رائعة من زهرة الاستوما البنفسجية الداكنة لاضافة لمسة متناغمة، ولمسة من الليمونيوم البنفسجي الفاتح. ستُبهرين من تُعجبين بهم بلا شك! دللوا أحباءكم بباقتنا الرائعة من المزهريات لتعبروا لهم عن مدى تقديركم لهم.\\nالارتفاع حوالي 30 سم.\\nالعرض حوالي 40 سم.\"}', '671', 'products/2023/06/101-43.png', '[\"products\\/gallery\\/2023\\/06\\/101-43.png\",\"products\\/gallery\\/2023\\/06\\/102-41.png\",\"products\\/gallery\\/2023\\/06\\/103-42.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17420,\"wp_en_id\":15282}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:28', '2026-10-13 12:58:22', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('187', '17430', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G387\",\"ar\":\"G387\"}', 'g387', 'g387-2', '{\"en\":\"Shine with elegance through this luxurious and creative bouquet a stunning blend of fresh fruits and vibrant flowers. It features green apples, oranges, strawberries, and cascading red and green grapes, paired with 10 pcs astrumeria, 40 pcs pink double colors roses, 15 pcs red baby roses, 10 pcs purple chrysanthemums, solidago, and 5 pcs pink limonium, all accented with natural greenery. Arranged in a sleek glass vase, it’s the perfect gift or centerpiece for any special occasion.\\nHeight approximately 95 cm.\\nWidth approximately 60 cm.\",\"ar\":\"تألق بتنسيق استثنائي ينبض بالفخامة والإبداع، يجمع بين روعة الزهور ونضارة الفواكه في تحفة فنية تأسر الأنظار! تتكوّن الباقة من 10 تفاح خضراء اللون  و15 حبة برتقال وفراولة شهية، إلى جانب عناقيد العنب الأحمر والأخضر المنسدلة بأناقة. ويكتمل السحر بـ10 زهور أستروميريا، و4 ورود مزدوجة باللون الوردي، و15 بيبي روز أحمر يضفي لمسة دفء، مع لمسات مميزة من الكريزنتيموم البنفسجي، و8 من زهور السوليداجو، وخمسة من الليمينيوم الوردي، تتخللها أوراق خضراء طبيعية تعزز من جمال التنسيق. توضع الباقة في فازة زجاجية أنيقة تُبرز تفاصيلها البديعة، لتكون خياراً مثالياً لهدية راقية أو ديكور يبهر في أي مناسبة.\\nالارتفاع حوالي 95 سم.\\nالعرض حوالي 60 سم.\"}', '647', 'products/2023/06/101-54.png', '[\"products\\/gallery\\/2023\\/06\\/101-54.png\",\"products\\/gallery\\/2023\\/06\\/104-45.png\",\"products\\/gallery\\/2023\\/06\\/102-51.png\",\"products\\/gallery\\/2023\\/06\\/103-51.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":17430,\"wp_en_id\":14962}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1100.00', '1100.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:28', '2026-10-13 13:04:57', NULL);
