INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('206', '17474', NULL, '[31,48,6,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G350\",\"ar\":\"G350\"}', 'g350', 'g350-2', '{\"en\":\"A meticulously crafted hand bouquet, presented with brilliance to our distinguished clients, immortalizing their unforgettable moments. Let feelings of love and optimism settle in the souls of your loved ones. This bouquet features 23 red roses with Lepidium greens.\\nHeight approximately 60 cm.\\nWidth approximately 40 cm.\",\"ar\":\"باقة يد صُممت بعناية فائقة .تُقدَّم بكل تألق لعملائنا المميزين، لتُخلّد لحظاتهم بلحظات لا تُنسى.\\nدع مشاعر الحب والتفاؤل تستقر في أرواح أحبائك المكونة من 23 وردة حمراء مع خضار اللبيديوم.\\nالارتفاع حوالي 60 سم.\\nالعرض حوالي 40 سم.\"}', '611', 'products/2023/06/101frontpng.png', '[\"products\\/gallery\\/2023\\/06\\/101frontpng.png\",\"products\\/gallery\\/2023\\/06\\/101-45.png\",\"products\\/gallery\\/2023\\/06\\/103-44.png\",\"products\\/gallery\\/2023\\/06\\/104-37.png\",\"products\\/gallery\\/2023\\/06\\/105-28.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17474,\"wp_en_id\":16530}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '200.00', '200.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:35', '2026-10-13 12:44:08', NULL);
