duation\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":137,\"name\":\"Ocassions\",\"slug\":\"ocassions\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"}],\"tags\":[],\"wp_ar_id\":17480,\"wp_en_id\":14640}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '270.00', '270.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:35', '2026-10-13 13:11:29', NULL);
