ight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17484,\"wp_en_id\":15112}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1200.00', '1200.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:35', '2026-10-13 13:00:33', NULL);
