:[],\"wp_ar_id\":17642,\"wp_en_id\":14998}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1600.00', '1600.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:48', '2026-10-13 13:03:11', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('285', '17644', NULL, '[31,48,6,20,8]', NULL, NULL, NULL, '{\"en\":\"G325\",\"ar\":\"G325\"}', 'g325', 'g325-2', '{\"en\":\"A fabulous vase bouquet of 15 Red Roses and White Roses arranged with White Lilium and Eustoma. Adding to the charm of this bouquet is the 2 Red Hypericum and 1 Hydrangea, White Baby Orchid and Chrysanthemum along with 4 Red Baby Roses. We have even included Green Kermit, Steel Grass along with twisted Bamboo for added allure, as our skilful florists artistically arranged this bouquet to make it an excellent gift for any occasions!\\nThe height is approximately 30 cm to 40 cm.\\nThe width is approximately 25 cm to 35 cm.\",\"ar\":\"التقط جمال الطبيعة الخلابة لتعبّر عن مشاعر الحب والإمتنان من خلال باقة في مزهرية رائعة من 15 روز احمر والأبيض مرتبة مع الليليوم والإيستوما البيضاء، بالإضافة إلى زهور 2 هايبركم و1 هيدرينجيا الحمراء مع البيبي أوركيد والكريزنتيموم البيضاء. أجمل المشاعر والأحاسيس تُرسل من خلال عبق 4 بيبي روز احمر والكيراميت الأخضر مع خضارات الإستيل وخضارات البامبو الملتوية لمزيد من الجمال، حيث قام بائعو الزهور الماهرون لدينا بترتيب هذه الباقة بشكل فني لجعلها هدية مميزة.\\nالارتفاع حوالي 30 سم إلى 40 سم.\\nالعرض حوالي 25 سم إلى 35 سم.\"}', '433', 'products/2023/06/g32520send20flower20to20jeddah201-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g32520send20flower20to20jeddah201-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g32520send20flower20to20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g32520send20flower20to20jeddah203-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g325-send-flower-to-jeddah-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"}],\"tags\":[],\"wp_ar_id\":17644,\"wp_en_id\":15116}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '400.00', '400.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:48', '2026-10-13 13:00:29', NULL);
