INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('320', '17724', NULL, '[31,19,50,48,6,21,26,4,45,22,23,12]', NULL, NULL, NULL, '{\"en\":\"G276\",\"ar\":\"G276\"}', 'g276', 'g276-2', '{\"en\":\"A refined arrangement that embodies purity and simplicity at their finest, featuring 10 white roses, 5 white baby orchids, and white baby roses, complemented by 3 white limonium and 4 white chrysanthemums, enhanced with carefully arranged greenery for a graceful touch. A timeless design that expresses elegance and serenity, perfect for any occasion.\\nHeight approximately 40 cm.\\nWidth approximately 35 cm.\",\"ar\":\"تنسيق راقٍ يجسد النقاء والبساطة في أبهى صورها، يتكوّن من 10 ورود بيضاء فاخرة تتناغم مع 5 بيبي أوركيد أبيض و4 بيبي روز أبيض، تتخللها لمسات ناعمة من لمينيوم أبيض (3) وكريزنتيموم أبيض (4)، مع خضار منسق بعناية يضيف عمقًا وأناقة. تصميم أنيق يناسب جميع المناسبات، يعبر عن الصفاء والرقي بأسلوب فخم وهادئ.\\nالارتفاع حوالي 40 سم.\\nالعرض حوالي 35 سم.\"}', '359', 'products/2023/06/2-31.png', '[\"products\\/gallery\\/2023\\/06\\/2-31.png\",\"products\\/gallery\\/2023\\/06\\/4-28.png\",\"products\\/gallery\\/2023\\/06\\/1-29.png\",\"products\\/gallery\\/2023\\/06\\/3-30.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17724,\"wp_en_id\":14680}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '250.00', '250.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:56', '2026-10-13 13:10:36', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('321', '17726', NULL, '[31,6,21,15,24,12,53]', NULL, NULL, NULL, '{\"en\":\"G275\",\"ar\":\"G275\"}', 'g275', 'g275-2', '{\"en\":\"Our expert florists will pick the most desirable combination of blooms to design a luxurious vase bouquet of Light Blue Hydrangea arranged with White Roses and Solidago which are mixed in with Green Kermit and Eucalyptus Berry for added beauty and delight.\\nTo complement this marvellous bouquet, we have also included some lovely  White Eustoma flowers along  which is perfectly highlighted by just the appropriate amount of White Chrysanthemum. This impressive vase bouquet is a gesture sure to make a lasting impression!\\nThe height is approximately 70 cm to 80 cm. The width is approximately 40 cm to 50 cm.\",\"ar\":\"عبّر عن حبك بعبق الزهور المُنعشة للروح. باقة في مزهرية فاخرة من الهيدرينجيا باللون الأزرق الفاتح مع الروز الابيض والسوليداجو، بالإضافة إلى الكيرميت الأخضر وخضارات اليوكاليبتوس لمزيد من الجمال.\\nاطلق العنان لمشاعرك الدافئة من خلال زهور الإستوما والكالا والكريزنتيموم البيضاء الرائع.\\nالارتفاع حوالي 70 سم إلى 80 سم. العرض حوالي 40 سم إلى 50 سم.\"}', '358', 'products/2023/06/artboard-4-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/artboard-4-1.jpg\",\"products\\/gallery\\/2023\\/06\\/artboard-2-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":151,\"name\":\"Green\",\"slug\":\"green\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"},{\"id\":189,\"name\":\"White Friday\",\"slug\":\"white-friday\"}],\"tags\":[],\"wp_ar_id\":17726,\"wp_en_id\":15270}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '800.00', '800.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:56', '2026-10-13 12:58:27', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('322', '17728', NULL, '[31,17,19,50,51,48,6,18,21,26,45,3,12,53]', NULL, NULL, NULL, '{\"en\":\"G274\",\"ar\":\"G274\"}', 'g274', 'g274-2', '{\"en\":\"The bright and stunning colours of this basket bouquet bring a longing for warmth and connection. Our fresh bouquet of White Hydrangea and Cymbidium mixed in with White Veronica and Lilium along with Green Kermit and White Chrysanthemum Purple. Adding to the charm is the White Tulips and Roses, as well as White Baby Orchid, Waxflowers and Snake Bamboo. Bring the joy into your beloved one’s life! The height is approximately 45 cm to 55 cm. The width is approximately 35 cm to 45 cm.\",\"ar\":\"الألوان الزاهية تجلب الرغبة بالدفء وتنعش الحواس في نفس الوقت. باقة في سلة أنيقة تحتوي على زهور طبيعية من الهيدرينجيا والسمبيديوم باللون الأبيض مع الفيرونيكا والليليوم الأبيض والواكس فلاور. ادخل الفرح والسعادة إلى حياة من تحب من خلال زهور الكريزنتيموم والتوليب والروز باللون الأبيض مع البيبي أوركيد الأبيض وخضارات البامبو الملتوية.\\nالارتفاع حوالي 45 سم إلى 55 سم.\\nالعرض حوالي 35 سم إلى 45 سم.\"}', '357', 'products/2023/06/g27420jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g27420jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g27420send20flower20to20jeddah20-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g27420send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g274-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"},{\"id\":189,\"name\":\"White Friday\",\"slug\":\"white-friday\"}],\"tags\":[],\"wp_ar_id\":17728,\"wp_en_id\":15014}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:56', '2026-10-13 13:02:34', NULL);
