INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('325', '17738', NULL, '[31,19,48,6,26,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G294\",\"ar\":\"G294\"}', 'g294', 'g294-2', '{\"en\":\"Our alluring basket bouquet blends two exceptional flowers such as 20 Red Roses and Green Cymbidium. This bouquet is proving increasingly popular for several factors, as it consists of White Lilium, Purple Waxflower and Eucalyptus Leaves combined with Korles Wood which have a phenomenal fragrance, and they are long-lasting.\\nThe height is approximately 45 cm to 55 cm.\\nThe width is approximately 35 cm to 45 cm.\",\"ar\":\"ارسم ابتسامة تعبّر عن السعادة على وجوه أحبتك من خلال باقة في السلة تجمع نوعين من الزهور الجذابة بشكل استثنائي مثل 20 روز احمر والسمبيديوم الأخضر. ارسل أجمل المشاعر من خلال أفضل الأزهار كالليليوم الأبيض والواكس فلاور البنفسجي مع خضارات الإكلابتوس وخشب الكورليس. هذه الباقة تتمتع برائحة استثنائية تُنعش الأرواح!\\nالارتفاع حوالي 45 سم إلى 55 سم.\\nالعرض حوالي 35 سم إلى 45 سم.\"}', '345', 'products/2023/06/g29420jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g29420jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g29420send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g294-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17738,\"wp_en_id\":14664}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '600.00', '600.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:57', '2026-10-13 13:11:01', NULL);
