lse,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17768,\"wp_en_id\":14716}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:58', '2026-10-13 13:09:51', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('340', '17770', NULL, '[31,19,48,6,26,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G241\",\"ar\":\"G241\"}', 'g241', 'g241-2', '{\"en\":\"An elegant arrangement that captures the luxury and allure of red, featuring 30 red roses radiating passion and beauty, delicately accented with white gypsophila and refined greenery for a touch of depth and freshness. A design that speaks of love and sophistication, perfect for expressing genuine emotions with timeless elegance.\",\"ar\":\"تنسيق أنيق يجسد فخامة اللون الأحمر ورونقه، يتكوّن من 30 وردة حمراء فاخرة تنبض بالشغف والجمال، تتخللها لمسات رقيقة من الجبسوفيليا البيضاء وخضار منسق بعناية تضيف عمقًا وحيوية للتصميم. تنسيق يعبر عن الحب والرقي في آنٍ واحد، مثالي لكل مناسبة تعبّر عن مشاعر صادقة بأسلوب أنيق ومؤثر.\\nالارتفاع حوالي 50 سم.\\nالعرض حوالي 30 سم.\"}', '312', 'products/2023/06/101-74.png', '[\"products\\/gallery\\/2023\\/06\\/101-74.png\",\"products\\/gallery\\/2023\\/06\\/102-70.png\",\"products\\/gallery\\/2023\\/06\\/104-62.png\",\"products\\/gallery\\/2023\\/06\\/105-37.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slu