INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('341', '17772', NULL, '[31,19,50,48,6,21,26,3,12]', NULL, NULL, NULL, '{\"en\":\"G239\",\"ar\":\"G239\"}', 'g239', 'g239-2', '{\"en\":\"A luxurious floral arrangement in soft shades of white and pink, featuring elegant white roses and carnations paired with pink eustnoma, liliums, and hypercom for a graceful, cheerful touch. Accented with white alstruemeria and gerbera blooms amid fresh greenery, and finished with pink and white balloons that add a festive charm — perfect for joyful occasions and thoughtful gifting.\\nHeight approximately 70 cm.\\nWidth approximately 50 cm.\",\"ar\":\"تنسيق زهري فاخر بتدرجات الأبيض والوردي، يجمع بين الورود البيضاء وزهرة القرنفل الناعم مع لمسات من الاستوما والليليوم والهايبركوم الوردية، في تناغم يعبّر عن الرقة والبهجة. تتوزع الستروميريا والجربيرا البيضاء بين الخضار الطبيعي لتمنح التصميم مظهرًا أنيقًا ومفعمًا بالحياة، فيما تضيف البالونات الوردية والبيضاء لمسة احتفالية ساحرة تجعل التنسيق مثاليًا للمناسبات السعيدة والهدايا المميزة.\\nالارتفاع حوالي 70 سم.\\nالعرض حوالي 65 سم.\"}', '310', 'products/2023/06/1-40.png', '[\"products\\/gallery\\/2023\\/06\\/1-40.png\",\"products\\/gallery\\/2023\\/06\\/02.png\",\"products\\/gallery\\/2023\\/06\\/03.png\",\"products\\/gallery\\/2023\\/06\\/4-42.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17772,\"wp_en_id\":16636}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:58', '2026-10-13 12:41:44', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('342', '17774', NULL, '[31,48,18,21,26,22,3]', NULL, NULL, NULL, '{\"en\":\"G235\",\"ar\":\"G235\"}', 'g235', 'g235-2', '{\"en\":\"Some emotions can’t be measured with words; express them through the elegance of flowers.\\nA bouquet that radiates beauty, spreads its fragrance in every corner, and gently touches the heart with feeling and grace.\\nA new collection with a modern design, carefully arranged by our expert florists, is a luxurious gift, perfect for those who hold a special place in your heart. Featuring white roses, elegant purple cymbidium stems, white gerbera, and delicate greenery.\\nHeight: approximately 60 cm to 65 cm\\nWidth: approximately 25 cm to 30 cm\",\"ar\":\"لأن بعض المشاعر لا تُقاس بالكلمات، عبّر عنها بأناقة الزهور. باقة تنبض بالجمال، تنثر عبيرها في كل زاوية، وتصل إلى القلوب بلطف وإحساس.\\nتشكيلة جديدة بتصميم عصري من تنسيق خبرائنا، تُقدَّم كباقة فاخرة ,تليق بمن استثنى مكانته في قلبك.\\nمكون من الروز الأبيض مع اغصان السمبيديوم البنفسجي الفاخر, والجربيرا الأبيض. وأضافة الخضار الرقيقة.\\nالارتفاع حوالي 60 سم إلى 65 سم.\\nالعرض حوالي 25 سم إلى 30 سم.\"}', '307', 'products/2023/06/102-7.jpg', '[\"products\\/gallery\\/2023\\/06\\/102-7.jpg\",\"products\\/gallery\\/2023\\/06\\/101-18.jpg\",\"products\\/gallery\\/2023\\/06\\/103-13.jpg\",\"products\\/gallery\\/2023\\/06\\/106-8.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"}],\"tags\":[],\"wp_ar_id\":17774,\"wp_en_id\":14724}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:58', '2026-10-13 13:09:41', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('343', '17776', NULL, '[31,19,50,48,6,21,16,22,3,23]', NULL, NULL, NULL, '{\"en\":\"G233\",\"ar\":\"G233\"}', 'g233', 'g233-2', '{\"en\":\"A beautiful vase bouquet consists of warm Yellow and 4 Red Roses that are loosely gathered with Pink Hydrangea and White Hypericum mixed in White Waxflower and Dark Purple Veronica for a touch of sweetness, along with White Chrysanthemum and Green Kermit as well as Snake Bamboo and Steel Grass Creating a gift that is full of joy and brightness. The height is approximately 30 cm to 35 cm. The width is approximately 15 cm to 25 cm.\",\"ar\":\"اجعل أحبائك يستشعرون جمال الحياة من خلال باقة في مزهرية جميلة تحتوي على الروز الأصفر و4 روز احمر الدافئ التي تم جمعها بشكل جميل مع الهيدرينجيا باللون الوردي مع الواكس فلاور والهايبركم باللون الأبيض. كما أضفنا زهور الفيرونيكا باللون الوردي الداكن والكريزنتيموم الأبيض للحصول على لمسة من الأناقة مع الكيراميت الأخضر وخضارات البامبو الملتوية وخضارات الإستيل لصنع هدية مليئة بالجمال والبهجة. الارتفاع حوالي 30 سم إلى 35 سم. العرض حوالي 15 سم إلى 25 سم.\"}', '305', 'products/2023/06/g23320jeddah20flower20delivery20grass2011-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g23320jeddah20flower20delivery20grass2011-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g23320jeddah20flower20delivery20grass2031-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g23320jeddah20flower20delivery20grass2041-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g23320jeddah20flower20delivery20grass20444-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g233-jeddah-flower-delivery-grass-21-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"}],\"tags\":[],\"wp_ar_id\":17776,\"wp_en_id\":15120}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '200.00', '200.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:58', '2026-10-13 13:00:25', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('344', '17778', NULL, '[31,19,48,6,28,4,20,8,47,12]', NULL, NULL, NULL, '{\"en\":\"G232\",\"ar\":\"G232\"}', 'g232', 'g232', '{\"en\":\"Bring a smile with the most beautiful flowers and become the reason they feel the endless joy of happiness.\\nThis vibrant hand bouquet features 15 red roses and red alstroemeria, paired with white matthiola, lilies, and chrysanthemums. Thoughtfully designed to express just how much you value the presence of your loved ones in your life.\\nHeight: 75 cm\\nWidth: 45 cm\",\"ar\":\"ارسم البسمة بأجمل الزهور على الإطلاق وكن السبب وراء استشعارهم بأنغام السعادة اللامتناهية من خلال باقة يد نابضة بالحياة تتكون من 15 حبه من الجوري الاحمر وأستوميريا الأحمر, مع الماثيولا والليليوم والكريزنتيموم الأبيض. صُممت هذه الباقة الجذابة لتظهر مدى تقديرك لوجود من أحببت في حياتك.\\nالارتفاع 75 سم.\\nالعرض حوالي 45سم.\"}', '304', 'products/2023/06/108.png', '[\"products\\/gallery\\/2023\\/06\\/108.png\",\"products\\/gallery\\/2023\\/06\\/104-7.png\",\"products\\/gallery\\/2023\\/06\\/105-6.png\",\"products\\/gallery\\/2023\\/06\\/107.png\",\"products\\/gallery\\/2023\\/06\\/102-5.png\",\"products\\/gallery\\/2023\\/06\\/103-7.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17778,\"wp_en_id\":16572}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:59', '2026-10-13 12:43:32', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('345', '17780', NULL, '[31,19,50,48,21,26,22,23,13]', NULL, NULL, NULL, '{\"en\":\"G227\",\"ar\":\"G227\"}', 'g227', 'g227-2', '{\"en\":\"A fabulous vase bouquet that contains Pink Roses, Pink Baby Orchid along with Pink Chrysanthemum, Snake Bamboo and Pink Hydrangea as well as Steel Grass gathered together into a stunning bouquet that delivers smiles for all of life’s special occasions or everyday moments. The height is approximately 35 cm to 45 cm. The width is approximately 20 cm to 30 cm.\",\"ar\":\"باقة مزهرية رائعة تحتوي على ورود وردية، وزهرة الأوركيد الوردية، بالإضافة إلى زهرة الأقحوان الوردية، وخيزران الثعبان، وزهرة الكوبية الوردية، بالإضافة إلى عشب الفولاذ، مجمعة معًا في باقة مذهلة تقدم الابتسامات في جميع المناسبات الخاصة أو اللحظات اليومية في الحياة. يبلغ ارتفاعه ما بين 35 سم إلى 45 سم تقريبًا. العرض حوالي 20 سم إلى 30 سم.\"}', '299', 'products/2023/06/g22720jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g22720jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g22720jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g227-send-flower-to-jeddah-600x600-1.jpg\"]', '{\"en\":null,\"ar\":\"<p>ارسل مشاعرك الجميلة بلغة لا تحتاج إلى ترجمة مكونة بأحرفٍ من زهر. باقة رائعة تحتوي على الروز والبيبي أوركيد باللون الوردي مع الخضارات البامبو الملتوية وخضارات الإستيل، بالإضافة إلى الهيدرينجيا والكريزنتيموم باللون الوردي. كن السبب الرئيسي وراء سعادتهم! الارتفاع حوالي 35 سم إلى 45 سم. العرض حوالي 20 سم إلى 30 سم.</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17780,\"wp_en_id\":15022}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:50:59', '2026-10-13 13:02:22', NULL);
