INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('359', '17814', NULL, '[31,48,21,4,16,22,3,23,9]', NULL, NULL, NULL, '{\"en\":\"G170\",\"ar\":\"G170\"}', 'g170', 'g170-2', '{\"en\":\"An excellent and beautiful gift to say thank you, congratulations, all the best or for any other occasion! Our gorgeous vase bouquet consists of elegant White Hydrangea and Yellow Roses arranged with White Veronica and White Bouvardia mixed in with Green Kermit and White Gypsophila that is loosely gathered with Solidago and White Chrysanthemum for a touch of freshness, creating a gift that is full of enjoyment and brightness. The height is approximately 30 cm to 40 cm. The width is approximately 20 cm to 30 cm.\",\"ar\":\"هدية جميلة وملائمة لأي من الاحتفالات أو المناسبات! باقة في مزهرية رائعة تتكون من الهيدرينجيا البيضاء والروز الأصفر مع زهور الفيرونيكا والبوفارديا باللون الأبيض الجذاب، بالإضافة إلى الكيراميت الأخضر والجيبسوفيليا البيضاء المُنسقة بشكل جميل مع السوليداجو والكريزنتيموم الأبيض للحصول على لمسة من الانتعاش مما يخلق هدية مليئة بالمتعة والبهجة. الارتفاع حوالي 30 سم إلى 40 سم. العرض حوالي 20 سم إلى 30 سم.\"}', '242', 'products/2023/06/g17020send20flower20to20jeddah-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g17020send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g17020send20flowers20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g170-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":145,\"name\":\"Yellow\",\"slug\":\"yellow\"}],\"tags\":[],\"wp_ar_id\":17814,\"wp_en_id\":14764}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '250.00', '250.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:06', '2026-10-13 13:08:49', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('360', '17816', NULL, '[31,51,48,6,18,21,4,25,2]', NULL, NULL, NULL, '{\"en\":\"G169\",\"ar\":\"G169\"}', 'g169', 'g169-2', '{\"en\":\"A bouquet in a vibrant vase resembles a passionate embrace that conveys your feelings to someone special. Our experts have created the latest attractive arrangements, combining elegance with green and white hydrangeas, with a delicate touch of Cumin crispedia. We’ve also added plenty of beautiful white baby orchids. Brighten their day with a bouquet of succulent greenery and twisted bamboo. This attractive bouquet, inspired by nature, is more than just a gift.\\nHeight approximately 45 cm to 55 cm. Width approximately 25 cm to 35 cm.\",\"ar\":\"باقة في مزهرية نابضة بالحياة تشبه العناق العاطفي الذي ينقل مشاعرك إلى شخص استثنائي. ابتكرو خبرائنا احدث التنسيقات الجذابة التي تجميع أناقتها من الهيدرينجيا الخضراء الروز والأبيض مع إضافة لمسه رائعة من كرسبيديا الكموني. قمنا أيضًا بالإضافة الكثير من زهور البيبي أوركيد الجميلة باللون الأبيض. اجعل أيامهم مليئة بالسعادة من خلال إهداء باقة من خضارات الإستيل وخضارات البامبو الملتوية. باقة جذابة مستوحاة من الطبيعة لتكون أكثر من مجرد هدية .\\nالارتفاع حوالي 45 سم إلى 55 سم. العرض حوالي 25 سم إلى 35 سم.\"}', '241', 'products/2023/06/front.jpg', '[\"products\\/gallery\\/2023\\/06\\/front.jpg\",\"products\\/gallery\\/2023\\/06\\/a-2.jpg\",\"products\\/gallery\\/2023\\/06\\/101-2jpgs-2.jpg\",\"products\\/gallery\\/2023\\/06\\/up.jpg\",\"products\\/gallery\\/2023\\/06\\/101jpgss.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":161,\"name\":\"Thank You\",\"slug\":\"thank-you\"},{\"id\":138,\"name\":\"Wedding\",\"slug\":\"wedding\"}],\"tags\":[],\"wp_ar_id\":17816,\"wp_en_id\":15334}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:06', '2026-10-13 12:57:40', NULL);
