55,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17822,\"wp_en_id\":16644}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '210.00', '210.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:06', '2026-10-13 12:41:32', NULL);
