INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('377', '17854', NULL, '[24,8,12]', NULL, NULL, NULL, '{\"en\":\"G122\",\"ar\":\"G122\"}', 'g-122', 'g-122', '{\"en\":\"Express the refined emotions your heart holds with this luxurious bouquet. new, modern arrangement crafted by our floral experts, featuring a stunning combination of red cymbidium and White eustoma Red and white roses Red baby roses Red hypericum berries Accented with solidago greenery Presented in a stylish vase to enhance the natural beauty and bring joy through the charm of nature.\\nHeight: 75 cm\\nWidth: 50 cm\",\"ar\":\"عبّر عما يحمله قلبك من مشاعر وأحاسيس راقية من خلال هذه الباقة الفاخرة, تشكيلة جديدة بتصميم عصري من تنسيق خبرائنا مكونه من السمبيديوم الأحمر والستوما الأبيض والجوري والبيبي جوري الأحمر والأبيض وخضارات السولي داغو مع الهايبركم الأحمر التي تقدم في مزهرية لمزيد من الجمال والاستمتاع بجمال الطبيعة الخلابة.\\nيبلغ الارتفاع 75 سم.\\nيبلغ العرض 50 سم.\"}', '194', 'products/2023/06/104-2.png', '[\"products\\/gallery\\/2023\\/06\\/104-2.png\",\"products\\/gallery\\/2023\\/06\\/101-2.png\",\"products\\/gallery\\/2023\\/06\\/102-1.png\",\"products\\/gallery\\/2023\\/06\\/103-2.png\",\"products\\/gallery\\/2023\\/06\\/105-2.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17854,\"wp_en_id\":14792}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '900.00', '900.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:08:22', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('378', '17858', NULL, '[31,17,19,6,18,3,23,13,8,12]', NULL, NULL, NULL, '{\"en\":\"G120\",\"ar\":\"G120\"}', 'g-120', 'g-120', '{\"en\":\"Fill your loved one’s day with love and happiness by sending this modern and beautifully arranged bouquet in a stunning basket. It features a charming combination of light pink roses, pink baby orchids, and pink carnations for a magical touch. A refreshing blend of light purple ustoma, white ustoma, and white matthiola Accented with red baby roses Your loved ones will be left speechless when this breathtaking floral masterpiece arrives at their doorstep.\\nHeight: 45 cm\\nWidth: 75 cm\",\"ar\":\"اجعل يوم من تحب مليء بالحب والسعادة وأرسل باقة عصرية رائعة بترتيب رقيق داخل سلة مذهلة تتكون من الجوري الزهري الفاتح مع البيبي أوركيد الوردي والكرنيشين باللون الوردي التي تعطي لمسة ساحرة. أنعش مشاعر أحبتك بباقة جميلة من أزهار الليمينوم البنفسجي الفاتح  والاستوما والماثيولا باللون الأبيض مع البيبي جوري الأحمر.\\nلن يتمكن أحبائك من العثور على التعبير المناسب لشكرك عندما تصل هذه التحفة الفنية الرائعة من الورود الطبيعية إلى عتبة منازلهم.\\nيبلغ الارتفاع حوالي 45سم.\\nالعرض حوالي 75 سم.\"}', '192', 'products/2023/06/106-3.png', '[\"products\\/gallery\\/2023\\/06\\/106-3.png\",\"products\\/gallery\\/2023\\/06\\/103-5.png\",\"products\\/gallery\\/2023\\/06\\/105-4.png\",\"products\\/gallery\\/2023\\/06\\/102-3.png\",\"products\\/gallery\\/2023\\/06\\/104-5.png\",\"products\\/gallery\\/2023\\/06\\/101-5.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17858,\"wp_en_id\":14796}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '420.00', '420.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:08:13', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('379', '17860', NULL, '[31,24,45]', NULL, NULL, NULL, '{\"en\":\"G119\",\"ar\":\"G119\"}', 'g119', 'g119-2', '{\"en\":\"This elegant bouquet is skillfully crafted with refined taste to leave an unforgettable impression, making it a refreshing and joyful gift for any occasion.\\nA luxurious bouquet in a vase featuring white Phalaenopsis, tulips, and 30 white roses, centered with dark green hydrangea and white lilies. Create beautiful moments with your loved ones!\\nHeight: approximately 95 to 100 cm\\nWidth: approximately 65 to 70 cm\",\"ar\":\"لأن بعض المشاعر لا تُقاس بالكلمات، عبّر عنها بأناقة الزهور. باقة تنبض بالجمال، تنثر عبيرها في كل زاوية، وتصل إلى القلوب بلطف وإحساس.\\nتشكيلة جديدة بتصميم عصري من تنسيق خبرائنا، تُقدَّم كباقة فاخرة فاخرة تليق بمن استثنى مكانته في قلبك.\\nمكون من الروز الأبيض مع اغصان السمبيديوم البنفسجي الفاخر, والجربيرا الأبيض. وأضافة الخضار الرقيقة.\\nالارتفاع حوالي 60 سم إلى 65 سم.\\nالعرض حوالي 25 سم إلى 30 سم.\"}', '191', 'products/2023/06/106-7.jpg', '[\"products\\/gallery\\/2023\\/06\\/106-7.jpg\",\"products\\/gallery\\/2023\\/06\\/105-3.jpg\",\"products\\/gallery\\/2023\\/06\\/104-2.jpg\",\"products\\/gallery\\/2023\\/06\\/102-4.jpg\",\"products\\/gallery\\/2023\\/06\\/103-3.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"}],\"tags\":[],\"wp_ar_id\":17860,\"wp_en_id\":15148}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1300.00', '1300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:00:00', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('380', '17864', NULL, '[31,19,48,6,21,4,20,3,8,47]', NULL, NULL, NULL, '{\"en\":\"G115\",\"ar\":\"G115\"}', 'g115', 'g115-2', '{\"en\":\"Our gorgeous box bouquet is the perfect gift, whether you say “Thank you” or you want to express your feelings in a fun and stylishly fashionable manner. Send this fun and bright bouquet and lighten up their day! A vibrant bouquet consists of 35 Red Roses and White Gypsophila along with Green Kermit and Steel Grass to play the role of complementing this colourful bouquet just beautifully.\\nThe height is approximately 25 cm to 35 cm.\\nThe width is approximately 25 cm to 35 cm.\",\"ar\":\"عبّر عن مشاعرك بطريقة مرحة وعصرية من خلال باقة في صندوق رائع لتكون هي الهدية المثالية لجميع أنواع الاحتفالات. أرسل هذه الباقة المشرقة وخفّف عليهم عناء يومهم من خلال كلمات من 35 روز أحمر والجيبسوفيليا البيضاء مع الكيراميت الأخضر وخضارات الإستيل لتضيف رونقًا من نوع آخر لحياتهم.\\nالارتفاع حوالي 25 سم إلى 35 سم.\\nالعرض حوالي 25 سم إلى 35 سم.\"}', '187', 'products/2023/06/g11520jedah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g11520jedah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g11520jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g11520send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g11520send20flowers20to20jeddah-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17864,\"wp_en_id\":15046}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:01:47', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('381', '17866', NULL, '[31,19,48,6,18,21,4,22,3,23,13]', NULL, NULL, NULL, '{\"en\":\"G113\",\"ar\":\"G113\"}', 'g113', 'g113-2', '{\"en\":\"A distinctive bouquet combining the most beautiful colors and luxurious flower types, featuring 22 dark pink roses, 2 pink lilies, 5 pink baby orchids, 4 light purple chrysanthemums, complemented by 3 purple limonium and natural greenery. This bouquet is a perfect choice for any occasion, where vibrant colors and an intricate design come together to create a touch of beauty and freshness, making it suitable for everyone of all ages.\\nHeight approximately 55 cm.\\nWidth approximately 45 cm.\",\"ar\":\"باقة مميزة تجمع بين أجمل الألوان والأنواع من الزهور الفاخرة، حيث تحتوي على 22 وردة روز وردي غامق، ليليوم وردي، أوركيد بيبي وردي، كريزنتيموم بنفسجي فاتح، إضافة إلى لمسات من لمينيوم بنفسجي وخضار طبيعي يضفي رونقاً طبيعياً على التصميم. تعد هذه الباقة خياراً رائعاً لأي مناسبة، حيث تتناغم الألوان الزاهية والتصميم المتقن لتخلق لمسة من الجمال والانتعاش، لتناسب ذوق الجميع من مختلف الأعمار.\\nالارتفاع حوالي 55 سم.\\nالعرض حوالي 45 سم.\"}', '185', 'products/2023/06/101-75.png', '[\"products\\/gallery\\/2023\\/06\\/101-75.png\",\"products\\/gallery\\/2023\\/06\\/104-63.png\",\"products\\/gallery\\/2023\\/06\\/103-68.png\",\"products\\/gallery\\/2023\\/06\\/102-69.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17866,\"wp_en_id\":14800}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:08:02', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('382', '17868', NULL, '[31,17,19,50,48,6,4,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G112\",\"ar\":\"G112\"}', 'g112', 'g112-2', '{\"en\":\"A striking bouquet gathered with fresh-picked Green Hydrangea and 32 Red Roses mixed in with White Lilium and Steel Grass along with a collection of greenery revealing the beauty of nature and creating a timeless gift for someone special to enjoy.\\nThe height is approximately 30 cm to 40 cm.\\nThe width is approximately 30 cm to 40 cm.\",\"ar\":\"فاجئ من تحب بهذه الزهور الرقيقة والجذابة. باقة رائعة تم تنسيقها مع الهيدرينجيا الخضراء و32 روز الأحمر، بالإضافة إلى الليليوم الأبيض وخضارات الإستيل لتكشف عن جمال الطبيعة وتخلق هدية لا مثيل لها.\\nالارتفاع حوالي 30 سم إلى 40 سم.\\nالعرض حوالي 30 سم إلى 40 سم.\"}', '184', 'products/2023/06/g11220jeddah20flower20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g11220jeddah20flower20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g11220send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g112-jeddah-flowers-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17868,\"wp_en_id\":14804}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:08', '2026-10-13 13:07:57', NULL);
