egories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17920,\"wp_en_id\":15062}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '470.00', '470.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:16', '2026-10-13 13:01:27', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('404', '17922', NULL, '[31,48,6,21,4,45,22,23,14,53]', NULL, NULL, NULL, '{\"en\":\"G058\",\"ar\":\"G058\"}', 'g058', 'g058-2', '{\"en\":\"This luxurious arrangement of white roses and white baby orchids is elegantly displayed in a simple glass vase, adding a touch of sophistication and tranquility to any space. The arrangement includes 12 soft white roses and 10 white baby orchids, with a meticulous design that highlights the beauty of nature in every detail. This arrangement is the perfect choice for decorating spaces or as a special gift for any occasion, offering a blend of elegance and softness.\\nHeight approximately 20 cm.\\nWidth approximately 20 cm.\",\"ar\":\"تتميز هذه التشكيلة الفاخرة من الورد الأبيض والبيبي أوركيد الأبيض بتنسيق أنيق داخل مزهرية زجاجية بسيطة، مما يضفي لمسة من الرقي والهدوء على أي مكان. تضم التشكيلة 12 روز بيضاء ناعمة و10 أوركيد بيبي أبيض، مع تنسيق متقن يبرز جمال الطبيعة بكل تفاصيلها. هذه التشكيلة تعتبر الخيار المثالي لتزيين الأماكن أو كهدية مميزة في المناسبات الخاصة، حيث توفر لمسة من الفخامة والنعومة في آن واحد.\\nالارتفاع حوالي 20 سم.\\nالعرض حوالي 20 سم.\"}', '129', 'products/2023/06/1-35.png', '[\"products\\/gallery\\/2023\\/06\\/1-35.png\",\"products\\/gallery\\/2023\\/06\\/2-37.png\",\"products\\/gallery\\/2023\\/06\\/3-36.png\",\"products\\/gallery\\/2023\\/06\\/4-33.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":150,\"name\":\"Peach\",\"slug\":\"peach\"},{\"id\":189,\"name\":\"White Friday\",\"slug\":\"white-friday\"}],\"tags\":[],\"wp_ar_id\":17922,\"wp_en_id\":14844}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '220.00', '220.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:16', '2026-10-13 13:07:14', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('405', '17928', NULL, '[31,17,48,6,18,21,26,4,3,25]', NULL, NULL, NULL, '{\"en\":\"G055\",\"ar\":\"G055\"}', 'g055', 'g055-2', '{\"en\":\"A luxurious floral bouquet featuring pink cymbidium flowers mixed with light and dark pink roses, pink lilies, snake bamboo, and steel grass.This bouquet makes a wonderful gift that everyone will appreciate for any occasion!\\nIt measures approximately 50-60 cm in height and 25-35 cm in width.\",\"ar\":\"عبّر عن حبك من خلال إهداء هذه الباقة الجميلة من الزهور المقطوفة بعناية,باقة مكونة من السيمبيديوم باللون البنفسجي مع الروز الوردي الفاتح والغامق والليليوم الوردي، كما أضفنا خضارات البامبو الملتوية وخضارات الإستيل التي تم جَمعُها في مزهرية فاخرة. باقة تسحر كل من يراها لتكون هي الهدية الأنسب لجميع المناسبات!\\nيبلغ الارتفاع حوالي 50 سم إلى 60 سم. العرض حوالي 25 سم إلى 35 سم.\"}', '126', 'products/2023/06/front-6.jpg', '[\"products\\/gallery\\/2023\\/06\\/front-6.jpg\",\"products\\/gallery\\/2023\\/06\\/ysar.jpg\",\"products\\/gallery\\/2023\\/06\\/ymyn-1.jpg\",\"products\\/gallery\\/2023\\/06\\/101jpgyy.jpg\",\"products\\/gallery\\/2023\\/06\\/101-11.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":161,\"name\":\"Thank You\",\"slug\":\"thank-you\"}],\"tags\":[],\"wp_ar_id\":17928,\"wp_en_id\":15066}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '650.00', '650.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:16', '2026-10-13 13:01:23', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('406', '17930', NULL, '[31,19,50,51,48,6,18,21,26,4,20,22,3,23,8,47,12]', NULL, NULL, NULL, '{\"en\":\"G054\",\"ar\":\"G054\"}', 'g054', 'g054-2', '{\"en\":\"Vase in a unique design of red roses, white calla, baby orchid, and white pink flower with steel grass\",\"ar\":\"أرسل هدية جذابة مليئة بأحاسيسك الدافئة! باقة زهور نابضة بالحياة من 17 روز احمر مع البيبي أوركيد والكالا باللون الأبيض. كما أضفنا خضارات الإستيل والكراميت الأخضر لإضافة لمسة من الخضرة التي تلعب دورًا أساسيًا في تصميم هذه الباقة الجميلة. أظهر مدى إمتنانك لوجود أحبائك في الحياة!\\nالارتفاع حوالي 25 سم إلى 35 سم.\\nالعرض حوالي 20 سم إلى 30 سم.\"}', '124', 'products/2023/06/g05420send20flower20to20jeddah201-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g05420send20flower20to20jeddah201-600x600-1.jpg\"]', '{\"en\":\"<p>Send a lovely gift that expresses how you feel! White callas and baby orchids are included with the 17 red roses. For a touch of greenery, we also add greens like still grass and cermet. Let your loved ones know how appreciative you are to have them in your life!<br />\\nHeight is about 25 cm to 35 cm.<br />\\nThe width is about 20 cm to 30 cm.</p>\",\"ar\":null}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17930,\"wp_en_id\":14852}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:16', '2026-10-13 13:07:09', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('407', '17932', NULL, '[31,48,21,24,13,52]', NULL, NULL, NULL, '{\"en\":\"G052\",\"ar\":\"G052\"}', 'g052', 'g052-2', '{\"en\":\"Express your feelings with the gentlest words and create beautiful moments in the lives of your loved ones with this stunning vase bouquet. It features white hydrangea and light pink roses, complemented by reddish-purple cymbidium orchids, Eustoma, alstroemeria, and light pink baby orchids. Delicate touches of light pink limonium and greenery, including steel grass and eucalyptus.\\nHeight: approximately 90 to 100 cm\\nWidth: approximately 60 to 65 cm\",\"ar\":\"عبّر عن مشاعرك بألطف الكلمات واصنع لحظات جميلة في حياة من تحب من خلال باقة في مزهرية رائعة تحتوي على الهيدرنيجا الأبيض والروز الأبيض والوردي الفاتح بإضافة زهور السمبيديوم باللون الاحمر وزهور الاستوما والاسترومريا والبيبي اوركيد البنك الفاتح مع لمسات الليمونيوم الزهري الفاتح وخضارات الستيل واليوكالبتوس .\\nالارتفاع حوالي 90 سم إلى 100 سم.\\nالعرض حوالي 60 سم إلى 65 سم.\"}', '123', 'products/2023/06/103-10.jpg', '[\"products\\/gallery\\/2023\\/06\\/103-10.jpg\",\"products\\/gallery\\/2023\\/06\\/101-23.jpg\",\"products\\/gallery\\/2023\\/06\\/105-4.jpg\",\"products\\/gallery\\/2023\\/06\\/102-5.jpg\",\"products\\/gallery\\/2023\\/06\\/106-2.jpg\",\"products\\/gallery\\/2023\\/06\\/104-3.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":160,\"name\":\"Luxury Bouquets\",\"slug\":\"luxury-bouquets\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":188,\"name\":\"PINK OCTOBER\",\"slug\":\"pink-october\"}],\"tags\":[],\"wp_ar_id\":17932,\"wp_en_id\":15322}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1100.00', '1100.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:16', '2026-10-13 12:57:51', NULL);
