INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('409', '17936', NULL, '[31,48,6,21,4,45,12]', NULL, NULL, NULL, '{\"en\":\"G047\",\"ar\":\"G047\"}', 'g047', 'g047-2', '{\"en\":\"A simple yet elegant arrangement that embodies purity and sophistication. Featuring 15 pristine white roses beautifully arranged in a clear glass vase, enhanced with fresh greenery that adds a touch of vitality and balance. A perfect choice to express sincerity, celebrate new beginnings, or bring a serene elegance to any space.\\nHeight approximately 20 cm.\\nWidth approximately 20 cm.\",\"ar\":\"تنسيق بسيط وأنيق يعكس الصفاء والرقي، يتكوّن من 15 روز بيضاء متناسقة داخل فازة زجاجية شفافة تضيف لمسة عصرية راقية. يكتمل جمال التنسيق بخضار طبيعي يمنح الترتيب لمسة من الحيوية والانتعاش. اختيار مثالي للتعبير عن النقاء، البدايات الجديدة، أو لتزيين المساحات بلمسة من الهدوء والجمال.\\nالارتفاع حوالي 20 سم.\\nالعرض حوالي 20 سم.\"}', '118', 'products/2023/06/1-25.png', '[\"products\\/gallery\\/2023\\/06\\/1-25.png\",\"products\\/gallery\\/2023\\/06\\/2-27.png\",\"products\\/gallery\\/2023\\/06\\/3-26.png\",\"products\\/gallery\\/2023\\/06\\/4-24.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17936,\"wp_en_id\":14856}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '150.00', '150.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:17', '2026-10-13 13:07:07', NULL);
