ers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":17944,\"wp_en_id\":15074}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:17', '2026-10-13 13:01:05', NULL);
