\"slug\":\"hand-bouquet\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":17946,\"wp_en_id\":15350}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '470.00', '470.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:17', '2026-10-13 12:57:24', NULL);
