INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('421', '17968', NULL, '[31,5,19,50,48,18,26,16,22,3,13,2]', NULL, NULL, NULL, '{\"en\":\"G017\",\"ar\":\"G017\"}', 'g017', 'g017-2', '{\"en\":\"Our vase bouquet of Pink and White Hydrangea mixed in Pink Lilium and White Baby Orchid combined with White Baby Roses and Pink Chrysanthemum along with the beautiful Pink Roses and Korles Wood that are said to be a symbol of beauty, luxury, and love, so what better flowers to beautify your special event!\\nThe height is approximately 45 cm to 55 cm.\\nThe width is approximately 35 cm to 45 cm.\",\"ar\":\"قمنا بجمع أجمل الزهور لنجعل أحبائك يشعرون بمزيد من التميز. باقة رائعة تحتوي على الهيدرينجيا باللون الوردي والأبيض مع الليلوم الوردي والبيبي أوركيد الأبيض. كما أضفنا لهذه الباقة الساحرة البيبي روز الأبيض والكريزنتيموم الوردي مع خشب الكورولوس والروز الوردي التي يقال أنها رمز للجمال والفخامة.\\nالارتفاع حوالي 45 سم إلى 55 سم.\\nالعرض حوالي 35 سم إلى 45 سم.\"}', '88', 'products/2023/06/g01720flower20delivery20jeddah202-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g01720flower20delivery20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g01720flower20delivery20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g017-flower-delivery-jeddah-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":141,\"name\":\"Best Seller\",\"slug\":\"best-seller\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"},{\"id\":138,\"name\":\"Wedding\",\"slug\":\"wedding\"},{\"id\":194,\"name\":\"\\u0627\\u0644\\u0623\\u0641\\u0636\\u0644 \\u0645\\u0628\\u064a\\u0639\\u0627\\u064b\",\"slug\":\"%d8%a7%d9%84%d8%a3%d9%81%d8%b6%d9%84-%d9%85%d8%a8%d9%8a%d8%b9%d8%a7%d9%8b\"}],\"tags\":[],\"wp_ar_id\":17968,\"wp_en_id\":14880}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '425.00', '425.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 13:06:47', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('422', '17970', NULL, '[31,5,19,50,21,26,28,16,22,3,23]', NULL, NULL, NULL, '{\"en\":\"G016\",\"ar\":\"G016\"}', 'g016', 'g016-2', '{\"en\":\"G16 – G16 – Mixed –\\nOur hand bouquet of White Hydrangea and Purple Roses mixed in Purple Baby Orchid and Purple Waxflower which are combined with Green Kermit and White Chrysanthemum that creates a meaningful gift for anyone! Plenty of ideal flowers such as Light Purple Chrysanthemum and Steel Grass along with leaves like Massangeana and Eucalyptus that makes an exquisite bouquet!\\nThe height is approximately 40 cm to 50 cm.\\nThe width is approximately 15 cm to 25 cm.\",\"ar\":\"ارسل هذه الباقة الجذابة إلى من تحب لتنقل لهم مشاعرك الصادقة من خلال هذه الأزهار الطبيعية. باقة يد مكونة من الهيدرينجيا البيضاء والروز البنفسجي مع البيبي أوركيد والواكس فلاور البنفسجي. كما أضفنا الكراميت الأخضر والكريزنتيموم الأبيض مما يخلق هدية ذات معنى لأي شخص! الكثير من الزهور الرائعة مثل الكريزنتيموم البنفسجي الفاتح وخضارات الإستيل مع خضارات الماسنجانا وخضارات الإكلابتوس تجعل هذه الباقة أكثر جمالًا وجاذبية!\\nالارتفاع حوالي 40 سم إلى 50 سم.\\nالعرض حوالي 15 سم إلى 25 سم.\"}', '87', 'products/2023/06/g01620flower20delivery20jeddah202-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g01620flower20delivery20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g01620flower20delivery20jeddah203-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g016-flower-delivery-jeddah-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":141,\"name\":\"Best Seller\",\"slug\":\"best-seller\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":194,\"name\":\"\\u0627\\u0644\\u0623\\u0641\\u0636\\u0644 \\u0645\\u0628\\u064a\\u0639\\u0627\\u064b\",\"slug\":\"%d8%a7%d9%84%d8%a3%d9%81%d8%b6%d9%84-%d9%85%d8%a8%d9%8a%d8%b9%d8%a7%d9%8b\"}],\"tags\":[],\"wp_ar_id\":17970,\"wp_en_id\":14884}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '180.00', '180.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 13:06:44', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('423', '17972', NULL, '[31,48,6,18,4,20,22,23,8,47]', NULL, NULL, NULL, '{\"en\":\"G015\",\"ar\":\"G015\"}', 'g015', 'g015-2', '{\"en\":\"Elegant and timeless, the Red Rose 35 arrangement captures the perfect balance of sophistication and charm. Featuring 35 fresh red roses beautifully arranged in a sleek glass vase wrapped with a luxurious black ribbon, this design expresses genuine emotions with style — ideal for any occasion, from heartfelt celebrations to refined gestures of appreciation.\\nHeight approximately 30 cm.\\nWidth approximately 36 cm.\",\"ar\":\"تأسر الأنظار ببساطتها وأناقتها، تنسيق روز أحمر 35 يجمع بين الفخامة والرقي في آنٍ واحد. باقة من 35 وردة حمراء طبيعية تنبض بالحياة، مرتبة بعناية داخل وعاء زجاجي أنيق يلفه شريط أسود فاخر، لتعبّر عن المشاعر الصادقة بأسلوب راقٍ يناسب كل المناسبات، من التهاني الرسمية إلى لحظات الحب والامتنان.\\nالارتفاع حوالي 30 سم.\\nالعرض حوالي 36 سم.\"}', '86', 'products/2023/06/1-33.png', '[\"products\\/gallery\\/2023\\/06\\/1-33.png\",\"products\\/gallery\\/2023\\/06\\/2-35.png\",\"products\\/gallery\\/2023\\/06\\/3-34.png\",\"products\\/gallery\\/2023\\/06\\/4-32.png\",\"products\\/gallery\\/2023\\/06\\/5-17.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17972,\"wp_en_id\":14888}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 13:06:40', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('424', '17974', NULL, '[31,48,6,18,4,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G014\",\"ar\":\"G014\"}', 'g014', 'g014-2', '{\"en\":\"A vase with 20 red roses as a gift for your loved ones and friends.\\nDesigned by our most skilled florists, our attractive vase bouquet contains 20 red roses, along with steel grass and eucalyptus leaves. Fill their homes or offices with the most luxurious roses you’ve ever seen!\\nIt measures approximately 30-40 cm in height and 15-25 cm in width.\",\"ar\":\"أطلق عنان مشاعرك لمن تحب. باقتنا الجذابة مُصممة\\nمن قبل أفضل الخبراء شغفًا ومهارة، حيث تضم ٢٠ من الروز الأحمر مع خضارات الإستيل\\nوخضارات اليوكالبتوس  . تملأ منازلهم أو مكاتبهم بأفخم\\nالورود التي يمكن رؤيتها على الإطلاق!\\nالارتفاع حوالي 30سم إلى 40 سم.\\nالعرض حوالي 15 سم إلى 25 سم.\"}', '85', 'products/2023/06/front-2.jpg', '[\"products\\/gallery\\/2023\\/06\\/front-2.jpg\",\"products\\/gallery\\/2023\\/06\\/ymyn.jpg\",\"products\\/gallery\\/2023\\/06\\/101jpgfok.jpg\",\"products\\/gallery\\/2023\\/06\\/aa.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17974,\"wp_en_id\":14892}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '280.00', '280.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 13:06:34', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('425', '17978', NULL, '[31,48,6,26,28,4,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G010\",\"ar\":\"G010\"}', 'g010', 'g010-2', '{\"en\":\"A sophisticated floral arrangement that perfectly blends luxury and simplicity. It features 25 vibrant red roses symbolizing deep emotion and timeless elegance, complemented by 5 pure white baby orchids that add a touch of grace and refinement. Surrounded by lush greenery for a balanced, captivating look — a perfect gift to express appreciation, love, or celebrate unforgettable moments.\\nHeight approximately 45 cm.\\nWidth approximately 40 cm.\",\"ar\":\"تنسيق أنيق يجمع بين الفخامة والبساطة في آنٍ واحد، يضم 25 روز حمراء متفتحة تعبّر عن المشاعر العميقة والأناقة الخالدة، تتوسطها 5 زهور بيبي أوركيد بيضاء تضيف لمسة من النقاء والرقي، وتحيط بها خضرة طبيعية تمنح التصميم توازنًا وجمالًا آسراً. تنسيق مثالي للتعبير عن التقدير، الحب، أو للاحتفال بلحظات لا تُنسى.\\nالارتفاع حوالي 45 سم.\\nالعرض حوالي 40 سم.\"}', '81', 'products/2023/06/1-24.png', '[\"products\\/gallery\\/2023\\/06\\/1-24.png\",\"products\\/gallery\\/2023\\/06\\/2-26.png\",\"products\\/gallery\\/2023\\/06\\/3-25.png\",\"products\\/gallery\\/2023\\/06\\/4-23.png\",\"products\\/gallery\\/2023\\/06\\/5-12.png\",\"products\\/gallery\\/2023\\/06\\/6-4.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":162,\"name\":\"Graduation\",\"slug\":\"graduation\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":140,\"name\":\"I am Sorry\",\"slug\":\"i-am-sorry\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":17978,\"wp_en_id\":14896}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '250.00', '250.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 13:06:30', NULL);
