الارتفاع حوالي25-30سم العرض حوالي 45-50سم</p>\"}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":153,\"name\":\"All Occasions\",\"slug\":\"all-occasions\"},{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":25751,\"wp_en_id\":25748}', NULL, NULL, NULL, NULL, NULL, NULL, '1', '380.00', '380.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:18', '2026-10-13 12:40:19', NULL);
