INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('436', '81928', NULL, '[31,16]', NULL, NULL, NULL, '{\"en\":\"G844\",\"ar\":\"G844\"}', 'g844', 'g844', '{\"en\":\"A flower basket thoughtfully crafted by our expert florists, who delicately arranged each element with refined taste to create a visually stunning and exclusive design. A harmonious blend of colors and fresh blooms, presented with elegance to our distinguished customers—perfect for capturing unforgettable moments. The bouquet includes a carefully selected array of flowers, including white and pink roses, touches of purple baby roses, white Eustoma flowers, and white and purple chrysanthemums, with elegant touches of white lilies and pink Limonium and a charming addition of light pink baby orchids, enhancing the aesthetics with the natural greenery of eucalyptus and steelgrass.\\nThis modern bouquet is suitable for all tastes.\\nHeight approximately 65 cm.\\nWidth approximately 55 cm.\",\"ar\":\"باقة زهور في سلة صُممت بعناية فائقة على يد خبرائنا، الذين أبدعوا في تنسيقها بذوق رفيع لتمنحك انطباعًا جماليًا راقيًا وحصريًا. مزيج متناغم من الألوان والأزهار الطبيعية، تُقدَّم بكل تألق لعملائنا المميزين، لتُخلّد لحظاتهم بلحظات لا تُنسى.\\nتضم الباقة من الأزهار المختارة بعناية ورود الجوري الأبيض والزهري ولمسات من البيبي جوري البنفسجي وزهور الاستوما الناعمة والكريزنتيموم بالأبيض والبنفسجي مع لمسات أنيقة من الليليوم الأبيض والليمينيوم الوردي إضافة ساحرة من البيبي أوركيد الوردي الفاتح تعزيز الجمالية بالخضارات الطبيعية من اليوكالبتوس والستيل غراس.\\nباقة حديثة مناسبة لكل لاذواق.\\nالارتفاع حوالي 65 سم.\\nالعرض حوالي 55 سم.\"}', 'GF-WP-81916', 'products/2025/08/104-front.png', '[\"products\\/gallery\\/2025\\/08\\/104-front.png\",\"products\\/gallery\\/2025\\/08\\/105-rhigt.png\",\"products\\/gallery\\/2025\\/08\\/101-lft.png\",\"products\\/gallery\\/2025\\/08\\/102up.png\",\"products\\/gallery\\/2025\\/08\\/101.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":152,\"name\":\"Mixed\",\"slug\":\"mixed\"}],\"tags\":[],\"wp_ar_id\":81928,\"wp_en_id\":81916}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '650.00', '650.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:19', '2026-10-13 12:39:45', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('437', '88360', NULL, '[31,45]', NULL, NULL, NULL, '{\"en\":\"G845\",\"ar\":\"G845\"}', 'g845', 'g845', '{\"en\":\"Express your love for your country through a natural flower bouquet inspired by national identity. This stunning arrangement features matthiola, white roses, green hypericum, and lush greenery, along with white chrysanthemums. A beautiful selection of flowers, this bouquet is your perfect choice for celebrating National Day!\\nHeight: Approximately 35 cm to 45 cm\\nWidth: Approximately 25 cm to 30 cm\",\"ar\":\"عبّر عن حبك لوطنك من خلال باقة الأزهار الطبيعية، المستوحاة من الهوية الوطنية. عبارة عن باقة رائعة المكونة من الماثيولا والجوري الأبيض, والهايبركم الأخضر مع خضارات الجميلة .بالإضافة الى الكريزنتيموم الأبيض. هذه الباقة المكونة من الأزهار الجميلة خيارك الأنسب للاحتفال باليوم الوطني!\\nالارتفاع حوالي 35 سم إلى 45 سم.\\nالعرض حوالي 25 سم إلى 30 سم.\"}', 'GF-WP-88359', 'products/2025/09/101-1.png', '[\"products\\/gallery\\/2025\\/09\\/101-1.png\",\"products\\/gallery\\/2025\\/09\\/102.png\",\"products\\/gallery\\/2025\\/09\\/104.png\",\"products\\/gallery\\/2025\\/09\\/105.png\",\"products\\/gallery\\/2025\\/09\\/103.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"}],\"tags\":[],\"wp_ar_id\":88360,\"wp_en_id\":88359}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '284.00', '284.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:19', '2026-10-13 12:39:36', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('438', '88401', NULL, '[31,45]', NULL, NULL, NULL, '{\"en\":\"G846\",\"ar\":\"G846\"}', 'g846', 'g846', '{\"en\":\"Express your love for your homeland with a sophisticated basket inspired by national identity, featuring natural flowers. It includes hydrangea, lilies, white roses, chrysanthemums, and green gypsophila. It also features beautiful eucalyptus and solidago greenery, as well as bamboo, a symbol of the homeland. This bouquet of beautiful flowers is the perfect choice for celebrating National Day!\\nHeight approximately 60 cm to 75 cm\\nWidth approximately 40 cm to 55 cm.\",\"ar\":\"عبّر عن حبك لوطنك من خلال سلة راقية، المستوحاة من الهوية الوطنية مكونه الأزهار الطبيعية. عبارة عن هيدرينجا والليليوم والجوري الأبيض,\\nمع الكريزنتيموم والجبسوفيليا الأخضر.\\nمع خضارات اليوكاليبتوس والسوليداجو الجميلة. بالإضافة الى البامبو التي يعطي رمزاً للوطن . هذه الباقة المكونة من الأزهار الجميلة خيارك الأنسب للاحتفال باليوم الوطني!\\nالارتفاع حوالي 60 سم إلى 75 سم.\\nالعرض حوالي 40 سم إلى 55 سم.\"}', 'GF-WP-88399', 'products/2025/09/101-min-1.png', '[\"products\\/gallery\\/2025\\/09\\/101-min-1.png\",\"products\\/gallery\\/2025\\/09\\/102-10.png\",\"products\\/gallery\\/2025\\/09\\/103-10.png\",\"products\\/gallery\\/2025\\/09\\/104-10.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"}],\"tags\":[],\"wp_ar_id\":88401,\"wp_en_id\":88399}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '500.00', '500.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:20', '2026-10-13 12:39:28', NULL);
