\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":181,\"name\":\"National Day\",\"slug\":\"national-day\"}],\"tags\":[],\"wp_ar_id\":88522,\"wp_en_id\":88505}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '412.00', '412.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:20', '2026-10-13 12:38:54', NULL);
