cts\\/gallery\\/2025\\/10\\/102-2.png\",\"products\\/gallery\\/2025\\/10\\/104-2.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":151,\"name\":\"Green\",\"slug\":\"green\"},{\"id\":164,\"name\":\"Hand Bouquet\",\"slug\":\"hand-bouquet\"},{\"id\":137,\"name\":\"Ocassions\",\"slug\":\"ocassions\"}],\"tags\":[],\"wp_ar_id\":88995,\"wp_en_id\":88985}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '380.00', '380.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:20', '2026-10-13 12:38:30', NULL);
