89260,\"wp_en_id\":89252}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '270.00', '270.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:25', '2026-10-13 12:37:44', NULL);
