gs\":[],\"wp_ar_id\":89463,\"wp_en_id\":89451}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '260.00', '260.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:40', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('472', '89474', NULL, '[40]', NULL, NULL, NULL, '{\"en\":\"G855\",\"ar\":\"G855\"}', 'g855', 'g855', '{\"en\":\"This exquisite gift combines natural beauty with luxurious elegance. It features a stunning of 25 soft red roses and two red Hypercom, carefully surrounded by fresh Strawberries that add a refreshing touch and delicious appeal. The blooming flowers paired with delicate greenery create a perfect balance of nature and refined style. The arrangement is beautifully finished with a sleek black ribbon, making it an ideal choice for special occasions like Valentine’s Day or memorable celebrations.\\nHeight approximately 25 cm.\\nWidth approximately 30 cm.\",\"ar\":\"هذه الهدية المميزة تجمع بين الجمال الطبيعي والرقي الفاخر. عبارة عن تركيبة ساحرة من 25 وردة روز حمراء ناعمة، وحبتان هايبركوم أحمر مغطاة بعناية حول حبات الفراولة الطازجة التي تضفي عليها لمسة من الانتعاش والطعم اللذيذ. بالإضافة إلى ذلك، فإن الزهور مع الخضار الرفيع في التصميم يخلق توازنًا بين الجمال الطبيعي واللمسات الرفيعة. تُختتم هذه الهدية الجميلة بشريط أسود أنيق، مما يجعلها مثالية للمناسبات الخاصة مثل عيد الحب أو الاحتفالات المميزة.   \\nالارتفاع حوالي 25 سم.\\nالعرض حوالي 35 سم.\"}', 'GF-WP-89464', 'products/2025/10/102-8.png', '[\"products\\/gallery\\/2025\\/10\\/102-8.png\",\"products\\/gallery\\/2025\\/10\\/103-11.png\",\"products\\/gallery\\/2025\\/10\\/104-5.png\",\"products\\/gallery\\/2025\\/10\\/101-16.png\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":176,\"name\":\"Fruits Bouquet\",\"slug\":\"fruits-bouquet\"}],\"tags\":[],\"wp_ar_id\":89474,\"wp_en_id\":89464}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '330.00', '330.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:34', NULL);
