INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('474', '90755', NULL, '[31,19,48,21,22,3,23,12]', NULL, NULL, NULL, '{\"en\":\"G424\",\"ar\":\"G424\"}', 'g424-1', 'g424-1', '{\"en\":\"Express your heartfelt emotions with this elegant and enchanting flower arrangement, a perfect way to say you care. This exquisite bouquet features a graceful mix of white roses, blue hydrangeas, white lilies, baby roses, eustoma, and white chrysanthemums, beautifully accented with baby orchids, white wax flowers, bamboo, and steel grass. Arranged in a stylish vase, this bouquet combines soft whites and serene blues for a look that radiates purity, peace, and affection. \\nHeight approximately 30cm to 40cm.\\nWidth approximately 20cm to 30cm.\",\"ar\":\"دلّلهم مع باقة مميزة في مزهرية أنيقة لتفصح لهم عن مشاعرك الصادقة. باقة ساحرة مليئة بالروز الأبيض والهيدرينجيا باللون الأزرق مع الليليوم والبيبي روز الأبيض، بالإضافة إلى الإيستوما والكريزنتيموم الأبيض مع البيبي أوركيد والواكس فلاور الأبيض، كما أضفنا البامبو والستيل جراس. الارتفاع حوالي 30 سم إلى 40 سم. العرض حوالي 20 سم إلى 30 سم\"}', '704', 'products/2023/06/g42420grass20flower2020delivery20jeddah202-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g42420grass20flower2020delivery20jeddah202-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g42420grass20flower2020delivery20jeddah203-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g42420grass20flower2020delivery20jeddah204-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g424-grass-flower-delivery-jeddah-1-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":158,\"name\":\"New Baby\",\"slug\":\"new-baby\"},{\"id\":139,\"name\":\"New Baby Girl\",\"slug\":\"new-baby-girl\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":90755,\"wp_en_id\":90756}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '300.00', '300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:22', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('475', '90768', NULL, '[31,19,51,48,18,13]', NULL, NULL, NULL, '{\"en\":\"G405\",\"ar\":\"G405\"}', 'g405', 'g405', '{\"en\":\"Express your feelings to your loved one with a vase containing 1  light pink Hydrangea, fuchsia Roses, 3 light pink Eustoma, 1\\nSolidago, 3 pink Matthiolas, 2 Twisted bamboos and purple\\nLimonium.\\nand heart-shaped steel grasses. Height about 50 cm Width about 40 cm\",\"ar\":\"عبر عن احساسك لمن تحب بفازة تحتوي على 1 من الهايدرينجا الوردي الفاتح و8 من الروز الفوشي و3 من الستوما الوردي الفاتح و3 من الماثيولا الوردي و2 من البامبو وأيضا 2 من اللمونيوم.\\nالارتفاع حوالي 50 سم العرض حوالي 40 سم\"}', '1115', 'products/2025/11/1.png', '[\"products\\/gallery\\/2025\\/11\\/1.png\",\"products\\/gallery\\/2025\\/11\\/2.png\",\"products\\/gallery\\/2025\\/11\\/3.png\",\"products\\/gallery\\/2025\\/11\\/4.png\",\"products\\/gallery\\/2025\\/11\\/5.png\",\"products\\/gallery\\/2025\\/11\\/6.png\"]', '{\"en\":\"<p><span style=\\\"font-weight: 400;\\\">Brighten someone’s day with the stunning floral arrangement, a joyful blend of soft pinks, purples, and whites elegantly gathered to bring warmth, beauty, and pure happiness to any moment. This charming bouquet features a hand-crafted selection of fresh blooms, including Pink and fuchsia roses, Hydrangea in a beautiful lavender-purple shade, White Lisianthus, and Seasonal accent flowers and greenery . Designed in a modern green vase, the arrangement offers a refreshing, vibrant aesthetic that makes it perfect for thoughtful gestures, celebrations, birthdays, thank-you moments, get-well wishes, or simply showing someone you care. Every flower is carefully selected for its freshness and color harmony, creating a bouquet that feels both luxurious and vibrant.</span></p>\",\"ar\":null}', '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":187,\"name\":\"For Father\",\"slug\":\"for-father\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":90768,\"wp_en_id\":90772}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:18', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('476', '91161', NULL, '[31,48,6,20,8,47]', NULL, NULL, NULL, '{\"en\":\"G823\",\"ar\":\"G823\"}', 'g823', 'g823', '{\"en\":\"Celebrate your sweetest moments with a refined vase arrangement presented in a clear round glass bowl. It pairs the cloud-soft elegance of white hydrangeas with the bold beauty of red tulips, finished with lush green leaf wrap inside the bowl for a clean, modern look. A thoughtful gift for anniversaries, birthdays, congratulations simply “just because” that speaks your heart with natural grace.\",\"ar\":\"استمتع بأجمل اللحظات مع أحبّتك وقدّم تنسيقًا زهريًا راقيًا داخل إناء زجاجي كروي شفاف يجمع بين رِقّة الهايدرينجا البيضاء وفخامة زهور التوليب الحمراء، مع لمسة أوراق خضراء ملتفّة داخل الوعاء لإطلالة عصرية أنيقة. هدية مثالية للتعبير عن الحب والامتنان في الذكرى السنوية وأعياد الميلاد والتهاني أو «بدون مناسبة»؛ فهي تنقل مشاعرك برونق طبيعي جميل يدوم في الذاكرة.\"}', '1357', 'products/2023/06/20alsabaa-220copy-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/20alsabaa-220copy-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/20alsabaa-320copy-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/alsabaa-1-copy-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":142,\"name\":\"For Him\",\"slug\":\"for-him\"},{\"id\":156,\"name\":\"Love\",\"slug\":\"love\"},{\"id\":144,\"name\":\"Red\",\"slug\":\"red\"},{\"id\":183,\"name\":\"Valentine\",\"slug\":\"valentine\"}],\"tags\":[],\"wp_ar_id\":91161,\"wp_en_id\":91163}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '320.00', '320.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:10', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('477', '91167', NULL, '[31,19,48,18,13]', NULL, NULL, NULL, '{\"en\":\"G685\",\"ar\":\"G685\"}', 'g685', 'g685', '{\"en\":\"A delicate expression of love and tenderness, this beautifully handcrafted bouquet features soft pink baby roses, white gypsophila, steel grass, and fresh green leaves, all wrapped elegantly in natural brown paper and tied with a satin pink ribbon. Perfect for birthdays, anniversaries, or to brighten someone’s day, this bouquet symbolizes affection, grace, and sweet emotions.\",\"ar\":\"عبّر عن مشاعرك الرقيقة مع هذه الباقة المصممة بعناية من قبل خبرائنا في تنسيق الزهور. تتألف من ورد بيبي روز وردي مع زهور الجبسوفيلا البيضاء وأوراق الستيل جراس والأوراق الخضراء الطبيعية، مغلفة بورق كرافت أنيق ومربوطة بشريط ساتان وردي. باقة مثالية للمناسبات الخاصة مثل أعياد الميلاد والذكرى السنوية أو لإدخال البهجة على قلب من تحب، فهي ترمز إلى الحنان والرقة والمشاعر الصادقة.\"}', '1240', 'products/2023/06/g68520jeddah20flowers20delivery20202-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g68520jeddah20flowers20delivery20202-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g68520jeddah20flowers20delivery20203-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g68520jeddah20flowers20delivery20204-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g68520jeddah20flowers20delivery20205-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g685-jeddah-flowers-delivery-1-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":167,\"name\":\"All Flowers\",\"slug\":\"all-flowers\"},{\"id\":155,\"name\":\"Birthday\",\"slug\":\"birthday\"},{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":149,\"name\":\"Pink\",\"slug\":\"pink\"}],\"tags\":[],\"wp_ar_id\":91167,\"wp_en_id\":91169}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '450.00', '450.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:07', NULL);
