gories\":[{\"id\":184,\"name\":\"For Her\",\"slug\":\"for-her\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"}],\"tags\":[],\"wp_ar_id\":91173,\"wp_en_id\":91175}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '350.00', '350.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:36:02', NULL);
INSERT INTO `products` (`id`, `source_id`, `user_id`, `category_id`, `production_id`, `sub_category_id`, `child_category_id`, `name`, `slug`, `slug_ar`, `sub_title`, `sku`, `image`, `gallery`, `description`, `meta_data`, `meta_tag_title`, `meta_tag_description`, `meta_tag_keywords`, `model`, `author`, `year`, `quantity`, `mrp`, `price`, `number_of_pages`, `book_language`, `weight`, `isbn`, `isbn10`, `isbn13`, `is_visible`, `is_subscription_enabled`, `subscription_discount_percentage`, `subscription_frequencies`, `subscription_durations`, `subscription_min_duration`, `type`, `updated_by`, `published_at`, `created_at`, `updated_at`, `vendor_id`) VALUES ('479', '91253', NULL, '[30,44,50,18]', NULL, NULL, NULL, '{\"en\":\"G384\",\"ar\":\"G384\"}', 'g384', 'g384', '{\"en\":\"Create unforgettable moments with the elegant blend of fresh natural flowers and premium chocolates. This stunning gift isn’t just a bouquet… It’s a heartfelt message, beautifully crafted to express emotions that words alone cannot capture. The collection features a refined selection of chocolates, including KitKat and Twix . Paired perfectly with a fresh floral arrangement designed with care, featuring White Gypsophila, Solidago, and Yellow Roses. With a height of approximately 40–50 cm and a width of 25–35 cm, this arrangement is beautifully sized to stand out and elevate any occasion, birthdays, congratulations, thank-you gestures, graduations, or simply showing someone you care. The harmonious blend of delicate blooms and gourmet chocolates makes an exceptional gift for those who genuinely deserve something special.\",\"ar\":\"اصنع لحظات لا تُنسى مع المزيج الأنيق من الزهور الطبيعية الطازجة والشوكولاتة الفاخرة.هذا التصميم الأنيق ليس مجرد هدي بل رسالة محبة تُقدَّم بذوق رفيع، وتُعبّر عن الامتنان والمشاعر الدافئة عندما لا تكفي الكلمات. يضم هذا التنسيق باقة راقية تحتوي على أفضل أنواع الشوكولاتة السويسرية من قطع الكيت كات وقطع التويكس، إلى جانب مجموعة من الزهور الطبيعية المنسّقة بعناية، تشمل الجيسوفيلّا البيضاء و خضار السوليداجو والروز الاصفر ، وتم تصميم الباقة بارتفاع يتراوح بين 40 إلى 50 سم وعرض 25 إلى 35 سم، مما يجعلها مناسبة تمامًا لكل المناسبات: أعياد الميلاد، التهاني، التخرّج، المناسبات الخاصة، وزيارات المحبة. هذا المزيج الساحر من الروائح الهادئة والشوكولاتة الفاخرة يجعلها هدية مثالية لكل من يستحق لحظة مختلفة مليئة بالسعادة.\"}', '642', 'products/2023/06/g38420jeddah20flowers20delivery-600x600-1.jpg', '[\"products\\/gallery\\/2023\\/06\\/g38420jeddah20flowers20delivery-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g38420send20flower20to20jeddah-600x600-1.jpg\",\"products\\/gallery\\/2023\\/06\\/g384-jeddah-flower-delivery-600x600-1.jpg\"]', NULL, '{\"type\":\"simple\",\"featured\":false,\"weight\":\"\",\"dimensions\":{\"length\":\"\",\"width\":\"\",\"height\":\"\"},\"categories\":[{\"id\":166,\"name\":\"Cake &amp; Chocolate\",\"slug\":\"cake-chocolate\"},{\"id\":180,\"name\":\"Chocolate Bouquet\",\"slug\":\"chocolate-bouquet\"},{\"id\":186,\"name\":\"Eid\",\"slug\":\"eid\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"}],\"tags\":[],\"wp_ar_id\":91253,\"wp_en_id\":91255}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '180.00', '180.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:35:57', NULL);
