:\"all-flowers\"},{\"id\":154,\"name\":\"For Mother\",\"slug\":\"for-mother\"},{\"id\":157,\"name\":\"Get well\",\"slug\":\"get-well\"},{\"id\":151,\"name\":\"Green\",\"slug\":\"green\"},{\"id\":159,\"name\":\"New job and promotion\",\"slug\":\"new-job-and-promotion\"},{\"id\":148,\"name\":\"White\",\"slug\":\"white\"}],\"tags\":[],\"wp_ar_id\":91259,\"wp_en_id\":91262}', NULL, NULL, NULL, NULL, NULL, NULL, '100', '1300.00', '1300.00', NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', '10.00', NULL, NULL, '3_months', 'Other', NULL, NULL, '2026-10-01 09:51:27', '2026-10-13 12:35:54', NULL);
